INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-5-17', 'ngsl-5', 'Thông dụng 2.001–2.500 · Bộ 17', 'New General Service List, thứ hạng 2.001–2.500', '#3da9fc', 'BookOpen', 17);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 1, 'weigh', 'cân; nặng (bao nhiêu); cân nhắc', 'verb', '[{"en":"How much does your suitcase weigh after packing all the gifts?","vi":"Vali của bạn nặng bao nhiêu sau khi xếp hết quà vào?"},{"en":"The nurse weighed the baby and wrote the number down.","vi":"Y tá cân em bé rồi ghi lại con số."},{"en":"You should weigh the pros and cons before changing jobs.","vi":"Bạn nên cân nhắc ưu và nhược điểm trước khi đổi việc."}]', '[{"phrase":"weigh the pros and cons"},{"phrase":"weigh the options"},{"phrase":"carefully weigh"}]', NULL, '/weɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wei/weigh/weigh__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 2, 'versus', 'đấu với; so với', 'preposition', '[{"en":"Tonight''s match is our school versus the team from the next town.","vi":"Trận đấu tối nay là trường mình đấu với đội đến từ thị trấn bên cạnh."},{"en":"We compared the cost of renting versus buying a home.","vi":"Chúng tôi đã so sánh chi phí giữa việc thuê nhà và mua nhà."},{"en":"For me, it''s always a question of quality versus quantity.","vi":"Với tôi, vấn đề luôn là chất lượng so với số lượng."}]', '[{"phrase":"quality versus quantity"},{"phrase":"cost versus benefit"}]', 'viết tắt: vs.', '/ˈvɜːrsəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/ver/versu/versus__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 3, 'deficit', 'thâm hụt; khoản thiếu hụt', 'noun', '[{"en":"The company ran a deficit for the second year in a row.","vi":"Công ty bị thâm hụt năm thứ hai liên tiếp."},{"en":"The government plans to reduce the budget deficit next year.","vi":"Chính phủ dự định giảm thâm hụt ngân sách vào năm sau."},{"en":"The country has a large trade deficit with its neighbors.","vi":"Nước này bị thâm hụt thương mại lớn với các nước láng giềng."}]', '[{"phrase":"budget deficit"},{"phrase":"trade deficit"},{"phrase":"reduce the deficit"}]', NULL, '/ˈdefɪsɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/def/defic/deficit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 4, 'modify', 'sửa đổi; điều chỉnh', 'verb', '[{"en":"We slightly modified the recipe to make it less sweet.","vi":"Chúng tôi đã điều chỉnh công thức một chút để món ăn bớt ngọt."},{"en":"You can modify your booking online up to 24 hours before arrival.","vi":"Bạn có thể sửa đổi thông tin đặt chỗ trên mạng chậm nhất 24 giờ trước khi đến."},{"en":"The car was modified to run on electricity.","vi":"Chiếc xe đã được sửa đổi để chạy bằng điện."}]', '[{"phrase":"slightly modify"},{"phrase":"modify the design"},{"phrase":"modify the rules"}]', NULL, '/ˈmɑːdɪfaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mod/modif/modify__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 5, 'flash', 'lóe lên; nháy (đèn)', 'verb', '[{"en":"Lightning flashed across the sky before the rain started.","vi":"Tia chớp lóe lên trên bầu trời trước khi trời đổ mưa."},{"en":"The driver behind us kept flashing his headlights.","vi":"Tài xế phía sau cứ nháy đèn pha với chúng tôi."},{"en":"An idea suddenly flashed through my mind during the meeting.","vi":"Một ý tưởng chợt lóe lên trong đầu tôi lúc đang họp."}]', '[{"phrase":"lights flash"},{"phrase":"flash your headlights"},{"phrase":"flash through your mind"}]', NULL, '/flæʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fla/flash/flash__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 6, 'friendship', 'tình bạn', 'noun', '[{"en":"Their close friendship began on the first day of college.","vi":"Tình bạn thân thiết của họ bắt đầu từ ngày đầu tiên học đại học."},{"en":"I value our friendship more than anything else.","vi":"Tôi trân trọng tình bạn của chúng ta hơn bất cứ điều gì."},{"en":"Can a friendship survive when you live in different countries?","vi":"Tình bạn có thể bền lâu không khi mỗi người sống ở một nước khác?"}]', '[{"phrase":"close friendship"},{"phrase":"lifelong friendship"},{"phrase":"value friendship"}]', NULL, '/ˈfrendʃɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fri/frien/friendship__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 7, 'profession', 'nghề nghiệp; ngành nghề', 'noun', '[{"en":"Nursing is a demanding profession, but she loves it.","vi":"Điều dưỡng là một nghề vất vả, nhưng cô ấy rất yêu nghề."},{"en":"What made you decide to join the medical profession?","vi":"Điều gì khiến bạn quyết định theo ngành y?"},{"en":"He is a lawyer by profession, but he writes novels too.","vi":"Nghề chính của anh ấy là luật sư, nhưng anh ấy cũng viết tiểu thuyết."}]', '[{"phrase":"medical profession"},{"phrase":"teaching profession"},{"phrase":"by profession"}]', NULL, '/prəˈfeʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/profe/profession__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 8, 'literally', 'theo nghĩa đen; thật sự', 'adverb', '[{"en":"Don''t take his joke literally; he was only teasing you.","vi":"Đừng hiểu câu đùa của anh ấy theo nghĩa đen, anh ấy chỉ trêu bạn thôi."},{"en":"I was so busy that I literally had no time to eat.","vi":"Tôi bận đến mức thật sự không có thời gian ăn."},{"en":"The hotel is literally five minutes from the beach.","vi":"Khách sạn thật sự chỉ cách bãi biển năm phút."}]', '[{"phrase":"take something literally"},{"phrase":"quite literally"},{"phrase":"translate literally"}]', NULL, '/ˈlɪtərəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lit/liter/literally__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 9, 'equation', 'phương trình; vấn đề cần cân nhắc', 'noun', '[{"en":"Can you help me solve this equation for my math homework?","vi":"Bạn giúp mình giải phương trình này trong bài tập toán được không?"},{"en":"The teacher wrote a long equation on the board.","vi":"Giáo viên viết một phương trình dài lên bảng."},{"en":"When choosing a job, salary is only one part of the equation.","vi":"Khi chọn việc, lương chỉ là một phần trong những điều cần cân nhắc."}]', '[{"phrase":"solve an equation"},{"phrase":"simple equation"},{"phrase":"part of the equation"}]', NULL, '/ɪˈkweɪʒn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/equ/equat/equation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 10, 'gesture', 'cử chỉ; nghĩa cử', 'noun', '[{"en":"She made a gesture for me to sit down.","vi":"Cô ấy ra dấu bảo tôi ngồi xuống."},{"en":"Sending flowers to your new neighbors is a nice gesture.","vi":"Gửi hoa tặng hàng xóm mới là một cử chỉ đẹp."},{"en":"In some cultures, this hand gesture is considered rude.","vi":"Ở một số nền văn hóa, cử chỉ tay này bị coi là bất lịch sự."}]', '[{"phrase":"make a gesture"},{"phrase":"nice gesture"},{"phrase":"hand gesture"}]', NULL, '/ˈdʒestʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/ges/gestu/gesture__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 11, 'entertain', 'giải trí; mua vui; tiếp đãi (khách)', 'verb', '[{"en":"The clown entertained the children for over an hour.","vi":"Chú hề mua vui cho bọn trẻ suốt hơn một tiếng."},{"en":"We love entertaining guests at home on weekends.","vi":"Chúng tôi thích tiếp đãi khách tại nhà vào cuối tuần."},{"en":"This book will keep you entertained on a long flight.","vi":"Cuốn sách này sẽ giúp bạn giải trí trên chuyến bay dài."}]', '[{"phrase":"entertain guests"},{"phrase":"keep someone entertained"},{"phrase":"entertain the crowd"}]', NULL, '/ˌentərˈteɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ent/enter/entertain__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 12, 'fantastic', 'tuyệt vời; tuyệt diệu', 'adjective', '[{"en":"We had a fantastic time at your wedding last weekend.","vi":"Chúng tôi đã có khoảng thời gian tuyệt vời ở đám cưới của bạn cuối tuần trước."},{"en":"You look fantastic in that blue dress!","vi":"Bạn mặc chiếc váy xanh dương đó trông tuyệt lắm!"},{"en":"The view from the top of the mountain was absolutely fantastic.","vi":"Quang cảnh từ đỉnh núi thật sự tuyệt vời."}]', '[{"phrase":"fantastic time"},{"phrase":"fantastic opportunity"},{"phrase":"absolutely fantastic"},{"phrase":"look fantastic"}]', NULL, '/fænˈtæstɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fan/fanta/fantastic__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 13, 'assign', 'giao (việc); phân công; chỉ định', 'verb', '[{"en":"Our teacher assigned us a lot of homework over the holiday.","vi":"Cô giáo giao cho chúng tôi rất nhiều bài tập về nhà trong kỳ nghỉ."},{"en":"The manager assigned three people to work on the new project.","vi":"Quản lý đã phân công ba người làm dự án mới."},{"en":"You will be assigned a seat when you check in.","vi":"Bạn sẽ được chỉ định chỗ ngồi khi làm thủ tục."}]', '[{"phrase":"assign homework"},{"phrase":"assign a task"},{"phrase":"assign someone to a project"}]', NULL, '/əˈsaɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assig/assign__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 14, 'inflation', 'lạm phát', 'noun', '[{"en":"Inflation has made groceries much more expensive this year.","vi":"Lạm phát khiến thực phẩm năm nay đắt hơn nhiều."},{"en":"Our salaries haven''t kept up with inflation.","vi":"Lương của chúng tôi không theo kịp lạm phát."},{"en":"The bank expects the inflation rate to fall next year.","vi":"Ngân hàng dự đoán tỷ lệ lạm phát sẽ giảm vào năm sau."}]', '[{"phrase":"inflation rate"},{"phrase":"high inflation"},{"phrase":"keep up with inflation"}]', 'không đếm được', '/ɪnˈfleɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inf/infla/inflation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 15, 'historic', 'có ý nghĩa lịch sử; cổ kính', 'adjective', '[{"en":"We walked around the historic center of the town.","vi":"Chúng tôi đi dạo quanh khu trung tâm cổ kính của thị trấn."},{"en":"Winning the cup was a historic moment for our small club.","vi":"Giành cúp là một khoảnh khắc lịch sử đối với câu lạc bộ nhỏ của chúng tôi."},{"en":"This historic building is over three hundred years old.","vi":"Tòa nhà cổ kính này đã hơn ba trăm năm tuổi."}]', '[{"phrase":"historic building"},{"phrase":"historic moment"},{"phrase":"historic site"}]', 'historic (có ý nghĩa lịch sử) ≠ historical (thuộc về lịch sử)', '/hɪˈstɔːrɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/his/histo/historic__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 16, 'injure', 'làm bị thương; gây chấn thương', 'verb', '[{"en":"She injured her knee while playing basketball with friends.","vi":"Cô ấy bị chấn thương đầu gối khi chơi bóng rổ với bạn bè."},{"en":"Be careful not to injure yourself when lifting heavy boxes.","vi":"Cẩn thận kẻo bị thương khi nâng những thùng nặng."},{"en":"Luckily, nobody was seriously injured in the accident.","vi":"May mắn là không ai bị thương nặng trong vụ tai nạn."}]', '[{"phrase":"seriously injured"},{"phrase":"badly injured"},{"phrase":"injure yourself"}]', NULL, '/ˈɪndʒər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inj/injur/injure__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 17, 'remote', 'xa xôi; hẻo lánh; từ xa', 'adjective', '[{"en":"They live in a remote village high in the mountains.","vi":"Họ sống ở một ngôi làng hẻo lánh trên núi cao."},{"en":"Many companies now allow remote work a few days a week.","vi":"Hiện nay nhiều công ty cho phép làm việc từ xa vài ngày mỗi tuần."},{"en":"Where did you put the remote control for the TV?","vi":"Bạn để cái điều khiển từ xa của TV ở đâu rồi?"}]', '[{"phrase":"remote area"},{"phrase":"remote village"},{"phrase":"remote work"},{"phrase":"remote control"}]', NULL, '/rɪˈməʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rem/remot/remote__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 18, 'therapy', 'liệu pháp; trị liệu', 'noun', '[{"en":"After the accident, he needed months of physical therapy.","vi":"Sau tai nạn, anh ấy cần vật lý trị liệu trong nhiều tháng."},{"en":"Music therapy can help children who often feel anxious.","vi":"Liệu pháp âm nhạc có thể giúp những trẻ hay lo âu."},{"en":"Going to therapy helped me handle stress at work.","vi":"Đi trị liệu tâm lý đã giúp tôi đối phó với căng thẳng trong công việc."}]', '[{"phrase":"physical therapy"},{"phrase":"music therapy"},{"phrase":"speech therapy"}]', NULL, '/ˈθerəpi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/thera/therapy__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 19, 'orange', 'quả cam; màu cam', 'noun', '[{"en":"I drink a glass of fresh orange juice every morning.","vi":"Mỗi sáng tôi uống một ly nước cam tươi."},{"en":"Could you peel an orange for your little brother?","vi":"Con bóc một quả cam cho em trai được không?"},{"en":"The sky turned a beautiful orange as the sun went down.","vi":"Bầu trời chuyển sang màu cam tuyệt đẹp khi mặt trời lặn."}]', '[{"phrase":"orange juice"},{"phrase":"peel an orange"},{"phrase":"bright orange"}]', NULL, '/ˈɔːrɪndʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ora/orang/orange__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-5-17', 20, 'twist', 'vặn; xoắn; trẹo (chân, tay)', 'verb', '[{"en":"Twist the lid to the left to open the jar.","vi":"Vặn nắp sang trái để mở lọ."},{"en":"I twisted my ankle while running down the stairs.","vi":"Tôi bị trẹo mắt cá chân khi chạy xuống cầu thang."},{"en":"He twisted the two wires together to fix the lamp.","vi":"Anh ấy xoắn hai sợi dây điện lại với nhau để sửa đèn."}]', '[{"phrase":"twist your ankle"},{"phrase":"twist the lid"},{"phrase":"twist and turn"}]', NULL, '/twɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/twi/twist/twist__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-6-01', 'ngsl-6', 'Thông dụng 2.501–2.809 · Bộ 1', 'New General Service List, thứ hạng 2.501–2.809', '#3da9fc', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 1, 'personnel', 'nhân sự; nhân viên', 'noun', '[{"en":"All personnel must wear a badge inside the building.","vi":"Tất cả nhân viên phải đeo thẻ khi ở trong tòa nhà."},{"en":"The company plans to cut personnel costs next year.","vi":"Công ty dự định cắt giảm chi phí nhân sự vào năm tới."},{"en":"Medical personnel arrived at the scene within minutes.","vi":"Nhân viên y tế đã có mặt tại hiện trường chỉ trong vài phút."}]', '[{"phrase":"medical personnel"},{"phrase":"military personnel"},{"phrase":"personnel costs"},{"phrase":"key personnel"}]', 'Thường dùng với động từ số nhiều; ≠ personal (adj): cá nhân', '/ˌpɜːrsəˈnel/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perso/personnel__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 2, 'imagination', 'trí tưởng tượng; óc sáng tạo', 'noun', '[{"en":"Children have a wonderful imagination and love telling stories.","vi":"Trẻ em có trí tưởng tượng tuyệt vời và rất thích kể chuyện."},{"en":"Use your imagination and draw whatever you like.","vi":"Hãy dùng trí tưởng tượng của bạn và vẽ bất cứ thứ gì bạn thích."},{"en":"This job requires imagination and a lot of hard work.","vi":"Công việc này đòi hỏi óc sáng tạo và rất nhiều sự chăm chỉ."}]', '[{"phrase":"use your imagination"},{"phrase":"vivid imagination"},{"phrase":"capture the imagination"}]', NULL, '/ɪˌmædʒɪˈneɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ima/imagi/imagination__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 3, 'disagree', 'không đồng ý; bất đồng', 'verb', '[{"en":"I disagree with you about the price of the house.","vi":"Tôi không đồng ý với bạn về giá của căn nhà."},{"en":"My parents often disagree about where to go on vacation.","vi":"Bố mẹ tôi thường bất đồng về việc đi nghỉ ở đâu."},{"en":"Few people would disagree that exercise is good for you.","vi":"Ít ai lại không đồng ý rằng tập thể dục tốt cho sức khỏe."}]', '[{"phrase":"disagree with"},{"phrase":"strongly disagree"},{"phrase":"disagree about"}]', 'disagree with sb / about sth', '/ˌdɪsəˈɡriː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disag/disagree__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 4, 'throat', 'cổ họng', 'noun', '[{"en":"I have a sore throat and a slight fever.","vi":"Tôi bị đau họng và hơi sốt."},{"en":"She cleared her throat before she began to speak.","vi":"Cô ấy hắng giọng trước khi bắt đầu nói."},{"en":"A small fish bone got stuck in his throat.","vi":"Một cái xương cá nhỏ bị mắc trong cổ họng anh ấy."}]', '[{"phrase":"sore throat"},{"phrase":"clear your throat"},{"phrase":"dry throat"}]', NULL, '/θrəʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thr/throa/throat__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 5, 'insight', 'sự hiểu biết sâu sắc; cái nhìn sâu sắc', 'noun', '[{"en":"This book gives us an insight into life in the 1800s.","vi":"Cuốn sách này cho chúng ta cái nhìn sâu sắc về cuộc sống vào thế kỷ 19."},{"en":"Her comments offered some useful insights into the problem.","vi":"Những nhận xét của cô ấy mang lại vài hiểu biết hữu ích về vấn đề này."},{"en":"Talking to customers gave us valuable insight into what they want.","vi":"Trò chuyện với khách hàng giúp chúng tôi hiểu sâu sắc hơn về những gì họ muốn."}]', '[{"phrase":"insight into"},{"phrase":"valuable insight"},{"phrase":"gain insight"},{"phrase":"provide insight"}]', 'insight into sth', '/ˈɪnsaɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insig/insight__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 6, 'tackle', 'giải quyết; xử lý', 'verb', '[{"en":"We need to tackle the problem before it gets worse.","vi":"Chúng ta cần giải quyết vấn đề trước khi nó trở nên tệ hơn."},{"en":"How should I tackle a big project with a short deadline?","vi":"Tôi nên xử lý một dự án lớn có thời hạn ngắn như thế nào?"},{"en":"The city is tackling traffic by building more bike lanes.","vi":"Thành phố đang giải quyết nạn kẹt xe bằng cách làm thêm làn đường cho xe đạp."}]', '[{"phrase":"tackle the problem"},{"phrase":"tackle an issue"},{"phrase":"tackle crime"}]', NULL, '/ˈtækl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tac/tackl/tackle__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 7, 'forever', 'mãi mãi; rất lâu', 'adverb', '[{"en":"I will remember this special day forever.","vi":"Tôi sẽ nhớ mãi ngày đặc biệt này."},{"en":"Nothing lasts forever, so enjoy the good times.","vi":"Không có gì tồn tại mãi mãi, vì vậy hãy tận hưởng những lúc tốt đẹp."},{"en":"The bus took forever to arrive this morning.","vi":"Sáng nay phải chờ rất lâu xe buýt mới đến."}]', '[{"phrase":"last forever"},{"phrase":"take forever"},{"phrase":"live forever"}]', 'take forever (khẩu ngữ): mất rất nhiều thời gian', '/fərˈevər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forev/forever__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 8, 'exceed', 'vượt quá; vượt', 'verb', '[{"en":"Drivers who exceed the speed limit will be fined.","vi":"Tài xế nào chạy quá tốc độ cho phép sẽ bị phạt."},{"en":"The final cost exceeded our budget by ten percent.","vi":"Chi phí cuối cùng vượt quá ngân sách của chúng tôi mười phần trăm."},{"en":"The hotel was lovely and exceeded all our expectations.","vi":"Khách sạn rất đẹp và vượt xa mọi kỳ vọng của chúng tôi."}]', '[{"phrase":"exceed the speed limit"},{"phrase":"exceed expectations"},{"phrase":"exceed the budget"}]', NULL, '/ɪkˈsiːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/excee/exceed__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 9, 'expenditure', 'chi tiêu; khoản chi', 'noun', '[{"en":"Our monthly expenditure on food has gone up a lot.","vi":"Chi tiêu hằng tháng cho thực phẩm của chúng tôi đã tăng lên nhiều."},{"en":"The school wants to reduce its expenditure on electricity.","vi":"Nhà trường muốn cắt giảm khoản chi cho tiền điện."},{"en":"Public expenditure on health care rose again last year.","vi":"Chi tiêu công cho y tế lại tăng vào năm ngoái."}]', '[{"phrase":"public expenditure"},{"phrase":"expenditure on"},{"phrase":"reduce expenditure"},{"phrase":"government expenditure"}]', 'expenditure on sth', '/ɪkˈspendɪtʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expen/expenditure__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 10, 'joy', 'niềm vui; nỗi vui sướng', 'noun', '[{"en":"The children jumped for joy when they saw the snow.","vi":"Bọn trẻ nhảy cẫng lên vì vui sướng khi nhìn thấy tuyết."},{"en":"Holding her baby for the first time filled her with joy.","vi":"Lần đầu được bế con khiến cô ấy tràn ngập niềm vui."},{"en":"Cooking for friends is one of my greatest joys.","vi":"Nấu ăn cho bạn bè là một trong những niềm vui lớn nhất của tôi."}]', '[{"phrase":"jump for joy"},{"phrase":"tears of joy"},{"phrase":"great joy"}]', NULL, '/dʒɔɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/joy/joy__/joy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 11, 'pregnant', 'có thai; mang bầu', 'adjective', '[{"en":"My sister is pregnant with her second child.","vi":"Chị gái tôi đang mang thai đứa con thứ hai."},{"en":"She was seven months pregnant when she stopped working.","vi":"Cô ấy nghỉ làm khi đang mang thai được bảy tháng."},{"en":"Pregnant women are advised not to drink any alcohol.","vi":"Phụ nữ mang thai được khuyên không nên uống rượu bia."}]', '[{"phrase":"get pregnant"},{"phrase":"pregnant women"},{"phrase":"months pregnant"}]', NULL, '/ˈpreɡnənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/pregn/pregnant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 12, 'reliable', 'đáng tin cậy', 'adjective', '[{"en":"I need a reliable car for my daily trip to work.","vi":"Tôi cần một chiếc xe đáng tin cậy để đi làm hằng ngày."},{"en":"Is this website a reliable source of information?","vi":"Trang web này có phải là nguồn thông tin đáng tin cậy không?"},{"en":"She''s always on time and very reliable.","vi":"Cô ấy luôn đúng giờ và rất đáng tin cậy."}]', '[{"phrase":"reliable source"},{"phrase":"reliable information"},{"phrase":"highly reliable"}]', NULL, '/rɪˈlaɪəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relia/reliable__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 13, 'gear', 'đồ nghề; thiết bị; số (xe)', 'noun', '[{"en":"Don''t forget to pack your camping gear.","vi":"Đừng quên xếp đồ cắm trại của bạn vào túi nhé."},{"en":"Cyclists should always wear the right safety gear.","vi":"Người đi xe đạp nên luôn mang đồ bảo hộ phù hợp."},{"en":"Put the car in first gear and slowly drive forward.","vi":"Hãy vào số một rồi từ từ cho xe chạy lên phía trước."}]', '[{"phrase":"camping gear"},{"phrase":"safety gear"},{"phrase":"first gear"}]', 'Nghĩa đồ nghề, thiết bị: không đếm được', '/ɡɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gea/gear_/gear__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 14, 'click', 'nhấp (chuột); bấm', 'verb', '[{"en":"Click the link below to download the file.","vi":"Nhấp vào đường liên kết bên dưới để tải tệp xuống."},{"en":"I clicked on the photo to make it bigger.","vi":"Tôi nhấp vào bức ảnh để phóng to nó."},{"en":"Click the Save button before you close the document.","vi":"Hãy bấm nút Lưu trước khi đóng tài liệu."}]', '[{"phrase":"click on"},{"phrase":"click the link"},{"phrase":"click the button"}]', 'click (on) sth', '/klɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cli/click/click__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 15, 'poet', 'nhà thơ', 'noun', '[{"en":"My grandfather was a poet and wrote about nature.","vi":"Ông tôi là một nhà thơ và viết về thiên nhiên."},{"en":"The poet read several of his poems to the students.","vi":"Nhà thơ đọc một vài bài thơ của mình cho các học sinh nghe."},{"en":"She dreamed of becoming a famous poet one day.","vi":"Cô ấy mơ ước một ngày nào đó trở thành nhà thơ nổi tiếng."}]', '[{"phrase":"famous poet"},{"phrase":"great poet"},{"phrase":"young poet"}]', NULL, '/ˈpəʊət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/poe/poet_/poet__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 16, 'fortune', 'gia tài; khoản tiền lớn; vận may', 'noun', '[{"en":"He made a fortune selling houses in the city.","vi":"Anh ấy kiếm được cả gia tài nhờ bán nhà ở thành phố."},{"en":"That new phone must have cost a fortune.","vi":"Chiếc điện thoại mới đó chắc hẳn tốn cả đống tiền."},{"en":"We had the good fortune to meet a kind local guide.","vi":"Chúng tôi may mắn gặp được một hướng dẫn viên địa phương tốt bụng."}]', '[{"phrase":"make a fortune"},{"phrase":"cost a fortune"},{"phrase":"good fortune"},{"phrase":"small fortune"}]', NULL, '/ˈfɔːrtʃən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/fortu/fortune__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 17, 'ceremony', 'buổi lễ; nghi lễ', 'noun', '[{"en":"The wedding ceremony will take place in the garden.","vi":"Lễ cưới sẽ được tổ chức trong khu vườn."},{"en":"Hundreds of parents attended the graduation ceremony.","vi":"Hàng trăm phụ huynh đã tham dự lễ tốt nghiệp."},{"en":"An opening ceremony was held for the new bridge.","vi":"Một buổi lễ khánh thành đã được tổ chức cho cây cầu mới."}]', '[{"phrase":"wedding ceremony"},{"phrase":"opening ceremony"},{"phrase":"graduation ceremony"},{"phrase":"attend a ceremony"}]', NULL, '/ˈserəməʊni/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cer/cerem/ceremony__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 18, 'pile', 'đống; chồng', 'noun', '[{"en":"There''s a pile of dirty clothes on the bedroom floor.","vi":"Có một đống quần áo bẩn trên sàn phòng ngủ."},{"en":"She put the letters in a neat pile on my desk.","vi":"Cô ấy xếp các lá thư thành một chồng gọn gàng trên bàn tôi."},{"en":"I have piles of homework to finish this weekend.","vi":"Cuối tuần này tôi có hàng đống bài tập về nhà phải làm xong."}]', '[{"phrase":"a pile of"},{"phrase":"piles of"},{"phrase":"neat pile"}]', NULL, '/paɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pil/pile_/pile__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 19, 'pig', 'con lợn; con heo', 'noun', '[{"en":"My uncle keeps pigs and chickens on his farm.","vi":"Chú tôi nuôi lợn và gà ở trang trại của chú."},{"en":"The little pig was rolling happily in the mud.","vi":"Chú lợn con đang lăn lộn vui vẻ trong bùn."},{"en":"Pigs are actually very clever and clean animals.","vi":"Lợn thực ra là loài vật rất thông minh và sạch sẽ."}]', '[{"phrase":"keep pigs"},{"phrase":"pig farm"},{"phrase":"pig farmer"}]', NULL, '/pɪɡ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pig/pig__/pig__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 20, 'mixture', 'hỗn hợp; sự pha trộn', 'noun', '[{"en":"Pour the mixture into a pan and bake for 30 minutes.","vi":"Đổ hỗn hợp vào khuôn và nướng trong 30 phút."},{"en":"Stir the flour and milk until the mixture is smooth.","vi":"Khuấy bột mì và sữa cho đến khi hỗn hợp mịn."},{"en":"I felt a strange mixture of excitement and fear.","vi":"Tôi cảm thấy một sự pha trộn kỳ lạ giữa háo hức và sợ hãi."}]', '[{"phrase":"a mixture of"},{"phrase":"strange mixture"},{"phrase":"cake mixture"}]', NULL, '/ˈmɪkstʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mix/mixtu/mixture__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 21, 'automatically', 'tự động; theo phản xạ', 'adverb', '[{"en":"The lights turn on automatically when someone enters the room.","vi":"Đèn tự động bật khi có người bước vào phòng."},{"en":"Your changes will be saved automatically every five minutes.","vi":"Các thay đổi của bạn sẽ được tự động lưu sau mỗi năm phút."},{"en":"When the phone rang, I automatically reached for it.","vi":"Khi điện thoại reo, tôi theo phản xạ với tay lấy nó."}]', '[{"phrase":"turn on automatically"},{"phrase":"happen automatically"},{"phrase":"automatically update"}]', NULL, '/ˌɔːtəˈmætɪkli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aut/autom/automatically__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 22, 'scholar', 'học giả', 'noun', '[{"en":"She is a respected scholar of Asian history.","vi":"Bà ấy là một học giả uy tín về lịch sử châu Á."},{"en":"Scholars have studied this old book for many years.","vi":"Các học giả đã nghiên cứu cuốn sách cổ này trong nhiều năm."},{"en":"The university invited a visiting scholar to give a talk.","vi":"Trường đại học đã mời một học giả thỉnh giảng đến nói chuyện."}]', '[{"phrase":"visiting scholar"},{"phrase":"leading scholar"},{"phrase":"respected scholar"}]', NULL, '/ˈskɑːlər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sch/schol/scholar__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 23, 'psychological', 'thuộc về tâm lý; tinh thần', 'adjective', '[{"en":"Losing a job can have serious psychological effects.","vi":"Mất việc có thể gây ra những ảnh hưởng tâm lý nghiêm trọng."},{"en":"The problem is psychological rather than physical.","vi":"Vấn đề nằm ở tâm lý chứ không phải ở thể chất."},{"en":"Athletes need psychological strength as well as physical training.","vi":"Vận động viên cần sức mạnh tinh thần cũng như sự rèn luyện thể chất."}]', '[{"phrase":"psychological effects"},{"phrase":"psychological problems"},{"phrase":"psychological pressure"},{"phrase":"psychological support"}]', NULL, '/ˌsaɪkəˈlɑːdʒɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/psy/psych/psychological__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 24, 'dramatically', 'đáng kể; mạnh mẽ; đột ngột', 'adverb', '[{"en":"House prices have risen dramatically in the last few years.","vi":"Giá nhà đã tăng mạnh trong vài năm qua."},{"en":"Her English improved dramatically after a year abroad.","vi":"Tiếng Anh của cô ấy tiến bộ vượt bậc sau một năm ở nước ngoài."},{"en":"The weather changed dramatically, and it started to snow.","vi":"Thời tiết thay đổi đột ngột và trời bắt đầu có tuyết."}]', '[{"phrase":"change dramatically"},{"phrase":"increase dramatically"},{"phrase":"rise dramatically"},{"phrase":"improve dramatically"}]', NULL, '/drəˈmætɪkli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dra/drama/dramatically__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 25, 'stake', 'cổ phần; điều được mất', 'noun', '[{"en":"The company bought a 20 percent stake in the hotel.","vi":"Công ty đã mua 20% cổ phần của khách sạn."},{"en":"Our jobs are at stake if the project fails.","vi":"Công việc của chúng tôi sẽ bị đe dọa nếu dự án thất bại."},{"en":"With so much money at stake, everyone felt nervous.","vi":"Có quá nhiều tiền có nguy cơ mất trắng nên ai cũng thấy lo lắng."}]', '[{"phrase":"at stake"},{"phrase":"a stake in"},{"phrase":"high stakes"},{"phrase":"majority stake"}]', 'at stake: đang bị đe dọa, có nguy cơ mất', '/steɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stake/stake__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 26, 'creature', 'sinh vật; loài vật', 'noun', '[{"en":"Many strange creatures live at the bottom of the sea.","vi":"Nhiều sinh vật kỳ lạ sống dưới đáy biển."},{"en":"Dogs are loyal creatures that need love and attention.","vi":"Chó là loài vật trung thành, cần được yêu thương và quan tâm."},{"en":"The movie is about a creature from another planet.","vi":"Bộ phim kể về một sinh vật đến từ hành tinh khác."}]', '[{"phrase":"living creature"},{"phrase":"strange creature"},{"phrase":"sea creature"}]', NULL, '/ˈkriːtʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cre/creat/creature__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 27, 'partnership', 'sự hợp tác; quan hệ đối tác', 'noun', '[{"en":"The two schools have formed a partnership to share resources.","vi":"Hai trường đã thiết lập quan hệ hợp tác để chia sẻ nguồn lực."},{"en":"Our company works in partnership with local farmers.","vi":"Công ty chúng tôi hợp tác với nông dân địa phương."},{"en":"Their business partnership lasted for more than twenty years.","vi":"Mối quan hệ đối tác kinh doanh của họ kéo dài hơn hai mươi năm."}]', '[{"phrase":"in partnership with"},{"phrase":"form a partnership"},{"phrase":"business partnership"}]', NULL, '/ˈpɑːrtnərʃɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/partn/partnership__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 28, 'participation', 'sự tham gia', 'noun', '[{"en":"Thank you for your participation in our survey.","vi":"Cảm ơn bạn đã tham gia khảo sát của chúng tôi."},{"en":"Student participation in class is part of the final grade.","vi":"Mức độ tham gia của sinh viên trên lớp được tính vào điểm tổng kết."},{"en":"The event encourages the participation of the whole community.","vi":"Sự kiện này khuyến khích sự tham gia của cả cộng đồng."}]', '[{"phrase":"participation in"},{"phrase":"active participation"},{"phrase":"encourage participation"},{"phrase":"public participation"}]', 'participation in sth', '/pɑːrˌtɪsɪˈpeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/parti/participation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-01', 29, 'clause', 'điều khoản; mệnh đề', 'noun', '[{"en":"Read every clause of the contract before you sign it.","vi":"Hãy đọc từng điều khoản trong hợp đồng trước khi ký."},{"en":"There is a clause that lets you cancel within 14 days.","vi":"Có một điều khoản cho phép bạn hủy trong vòng 14 ngày."},{"en":"A main clause can stand alone as a complete sentence.","vi":"Mệnh đề chính có thể đứng riêng như một câu hoàn chỉnh."}]', '[{"phrase":"contract clause"},{"phrase":"main clause"},{"phrase":"relative clause"}]', NULL, '/klɔːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cla/claus/clause__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-6-02', 'ngsl-6', 'Thông dụng 2.501–2.809 · Bộ 2', 'New General Service List, thứ hạng 2.501–2.809', '#3da9fc', 'BookOpen', 2);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 1, 'penalty', 'hình phạt; tiền phạt; quả phạt đền', 'noun', '[{"en":"You will have to pay a penalty if you return the book late.","vi":"Bạn sẽ phải nộp tiền phạt nếu trả sách muộn."},{"en":"The penalty for cheating on the exam is very serious.","vi":"Hình phạt cho việc gian lận trong kỳ thi rất nặng."},{"en":"He scored from a penalty in the last minute of the game.","vi":"Anh ấy ghi bàn từ quả phạt đền ở phút cuối trận đấu."}]', '[{"phrase":"pay a penalty"},{"phrase":"heavy penalty"},{"phrase":"penalty kick"}]', NULL, '/ˈpenəlti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pen/penal/penalty__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 2, 'chamber', 'phòng; buồng; khoang', 'noun', '[{"en":"The meeting was held in the council chamber downstairs.","vi":"Cuộc họp được tổ chức ở phòng họp hội đồng dưới tầng."},{"en":"The heart has four chambers that pump blood around the body.","vi":"Tim có bốn buồng bơm máu đi khắp cơ thể."},{"en":"Tourists can visit the old burial chamber inside the pyramid.","vi":"Du khách có thể tham quan phòng mộ cổ bên trong kim tự tháp."}]', '[{"phrase":"council chamber"},{"phrase":"burial chamber"},{"phrase":"chamber of commerce"}]', NULL, '/ˈtʃeɪmbər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chamb/chamber__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 3, 'fancy', 'sang trọng; cầu kỳ, kiểu cách', 'adjective', '[{"en":"We went to a fancy restaurant for our wedding anniversary.","vi":"Chúng tôi đi ăn ở một nhà hàng sang trọng nhân dịp kỷ niệm ngày cưới."},{"en":"I don''t need a fancy phone, just one that works well.","vi":"Tôi không cần một chiếc điện thoại xịn, chỉ cần nó dùng tốt."},{"en":"Her dress was too fancy for a simple picnic in the park.","vi":"Chiếc váy của cô ấy quá cầu kỳ cho một buổi dã ngoại đơn giản trong công viên."}]', '[{"phrase":"fancy restaurant"},{"phrase":"fancy hotel"},{"phrase":"nothing fancy"}]', 'Anh-Anh còn dùng làm động từ: fancy = thích, muốn', '/ˈfænsi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fan/fancy/fancy__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 4, 'poetry', 'thơ; thơ ca', 'noun', '[{"en":"She has been writing poetry since she was a teenager.","vi":"Cô ấy đã làm thơ từ khi còn là thiếu niên."},{"en":"We read some Vietnamese poetry in class today.","vi":"Hôm nay chúng tôi đọc một số bài thơ Việt Nam trên lớp."},{"en":"His poetry is simple but full of feeling.","vi":"Thơ của anh ấy giản dị nhưng giàu cảm xúc."}]', '[{"phrase":"write poetry"},{"phrase":"read poetry"},{"phrase":"love poetry"},{"phrase":"modern poetry"}]', 'không đếm được; một bài thơ = a poem', '/ˈpəʊətri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/poe/poetr/poetry__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 5, 'chat', 'trò chuyện; nhắn tin trò chuyện (trên mạng)', 'verb', '[{"en":"We chatted for hours about our school days.","vi":"Chúng tôi trò chuyện hàng giờ liền về thời đi học."},{"en":"I often chat online with my cousins in the evening.","vi":"Buổi tối tôi thường nhắn tin trò chuyện với anh chị em họ trên mạng."},{"en":"Can we chat after the meeting instead of right now?","vi":"Chúng ta nói chuyện sau cuộc họp thay vì bây giờ được không?"}]', '[{"phrase":"chat with friends"},{"phrase":"chat online"},{"phrase":"have a chat"}]', NULL, '/tʃæt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chat_/chat__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 6, 'clothing', 'quần áo; trang phục', 'noun', '[{"en":"Please bring warm clothing because it gets cold at night.","vi":"Hãy mang theo quần áo ấm vì ban đêm trời trở lạnh."},{"en":"This store sells clothing for children and teenagers.","vi":"Cửa hàng này bán quần áo cho trẻ em và thanh thiếu niên."},{"en":"Workers must wear protective clothing in the factory.","vi":"Công nhân phải mặc đồ bảo hộ trong nhà máy."}]', '[{"phrase":"warm clothing"},{"phrase":"protective clothing"},{"phrase":"piece of clothing"},{"phrase":"clothing store"}]', 'không đếm được; một món đồ = a piece of clothing', '/ˈkləʊðɪŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/clo/cloth/clothing__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 7, 'evolve', 'tiến hóa; phát triển dần', 'verb', '[{"en":"Scientists believe that birds evolved from small dinosaurs.","vi":"Các nhà khoa học tin rằng chim tiến hóa từ những loài khủng long nhỏ."},{"en":"The small shop has slowly evolved into a large company.","vi":"Cửa hàng nhỏ ấy đã dần phát triển thành một công ty lớn."},{"en":"Language is always evolving as people find new ways to speak.","vi":"Ngôn ngữ luôn phát triển khi con người tìm ra những cách nói mới."}]', '[{"phrase":"evolve from"},{"phrase":"evolve into"},{"phrase":"evolve over time"}]', NULL, '/ɪˈvɑːlv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/evo/evolv/evolve__us_5.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 8, 'sake', 'vì (lợi ích của ai/cái gì)', 'noun', '[{"en":"She gave up sugar for the sake of her health.","vi":"Cô ấy bỏ đường vì sức khỏe của mình."},{"en":"Please be quiet for the baby''s sake; she''s finally asleep.","vi":"Làm ơn giữ yên lặng vì em bé, cuối cùng bé cũng ngủ rồi."},{"en":"Don''t change your plans just for my sake.","vi":"Đừng thay đổi kế hoạch chỉ vì tôi."}]', '[{"phrase":"for the sake of"},{"phrase":"for your own sake"},{"phrase":"for safety''s sake"}]', 'thường dùng trong cụm for the sake of / for someone''s sake', '/ˈseɪk/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 9, 'shelf', 'kệ; giá (để đồ)', 'noun', '[{"en":"Put the books back on the shelf when you finish.","vi":"Hãy đặt sách lại lên kệ khi bạn đọc xong."},{"en":"The top shelf is too high for me to reach.","vi":"Kệ trên cùng cao quá, tôi với không tới."},{"en":"The store''s shelves were empty before the big storm.","vi":"Các kệ hàng của cửa hàng trống trơn trước cơn bão lớn."}]', '[{"phrase":"top shelf"},{"phrase":"on the shelf"},{"phrase":"bottom shelf"}]', 'số nhiều: shelves', '/ʃelf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/she/shelf/shelf__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 10, 'boost', 'thúc đẩy; làm tăng, nâng cao', 'verb', '[{"en":"A short walk can boost your energy in the afternoon.","vi":"Đi bộ một chút có thể giúp bạn tăng năng lượng vào buổi chiều."},{"en":"The new park has boosted tourism in our town.","vi":"Công viên mới đã thúc đẩy du lịch ở thị trấn chúng tôi."},{"en":"Winning the prize really boosted her confidence.","vi":"Việc giành giải thực sự đã nâng cao sự tự tin của cô ấy."}]', '[{"phrase":"boost confidence"},{"phrase":"boost sales"},{"phrase":"boost the economy"}]', NULL, '/buːst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/boo/boost/boost__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 11, 'tail', 'đuôi; phần đuôi', 'noun', '[{"en":"The dog wagged its tail when we came home.","vi":"Con chó vẫy đuôi khi chúng tôi về nhà."},{"en":"Monkeys use their long tails to hold on to branches.","vi":"Khỉ dùng chiếc đuôi dài để bám vào cành cây."},{"en":"The tail of the plane was painted bright red.","vi":"Phần đuôi máy bay được sơn màu đỏ tươi."}]', '[{"phrase":"wag its tail"},{"phrase":"long tail"},{"phrase":"heads or tails"}]', NULL, '/teɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tai/tail_/tail__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 12, 'possession', 'đồ đạc, tài sản; sự sở hữu', 'noun', '[{"en":"She packed all her possessions into two small bags.","vi":"Cô ấy xếp toàn bộ đồ đạc của mình vào hai chiếc túi nhỏ."},{"en":"This old watch is my most treasured possession.","vi":"Chiếc đồng hồ cũ này là món đồ quý giá nhất của tôi."},{"en":"Visitors must have their passports in their possession at all times.","vi":"Du khách phải luôn mang theo hộ chiếu bên mình."}]', '[{"phrase":"personal possessions"},{"phrase":"prized possession"},{"phrase":"in possession of"}]', NULL, '/pəˈzeʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/posse/possession__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 13, 'abortion', 'sự phá thai', 'noun', '[{"en":"The doctor explained the risks of abortion to the patient.","vi":"Bác sĩ giải thích cho bệnh nhân những rủi ro của việc phá thai."},{"en":"Abortion laws are different from one country to another.","vi":"Luật về phá thai khác nhau giữa các quốc gia."},{"en":"Many hospitals give advice to women who are considering an abortion.","vi":"Nhiều bệnh viện tư vấn cho những phụ nữ đang cân nhắc việc phá thai."}]', '[{"phrase":"have an abortion"},{"phrase":"abortion law"}]', NULL, '/əˈbɔːrʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abo/abort/abortion__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 14, 'curious', 'tò mò; lạ, kỳ lạ', 'adjective', '[{"en":"Children are naturally curious about the world around them.","vi":"Trẻ em vốn tò mò về thế giới xung quanh."},{"en":"I''m curious to know what happened at the party.","vi":"Tôi tò mò muốn biết chuyện gì đã xảy ra ở bữa tiệc."},{"en":"There was a curious smell coming from the kitchen.","vi":"Có một mùi lạ bốc ra từ nhà bếp."}]', '[{"phrase":"curious about"},{"phrase":"curious to know"},{"phrase":"naturally curious"}]', NULL, '/ˈkjʊriəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cur/curio/curious__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 15, 'wooden', 'bằng gỗ', 'adjective', '[{"en":"We sat on a wooden bench near the lake.","vi":"Chúng tôi ngồi trên một chiếc ghế dài bằng gỗ gần hồ."},{"en":"My grandfather made this wooden box by hand.","vi":"Ông tôi đã tự tay làm chiếc hộp gỗ này."},{"en":"The children played with wooden toys in the garden.","vi":"Bọn trẻ chơi đồ chơi bằng gỗ trong vườn."}]', '[{"phrase":"wooden table"},{"phrase":"wooden floor"},{"phrase":"wooden box"},{"phrase":"wooden spoon"}]', NULL, '/ˈwʊdn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/woo/woode/wooden__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 16, 'boom', 'sự bùng nổ, phát triển nhanh; tiếng nổ ầm', 'noun', '[{"en":"The town grew quickly during the tourism boom.","vi":"Thị trấn phát triển nhanh trong thời kỳ bùng nổ du lịch."},{"en":"There has been a boom in online shopping recently.","vi":"Gần đây mua sắm trực tuyến đã bùng nổ."},{"en":"A loud boom of thunder woke the baby up.","vi":"Một tiếng sấm nổ ầm làm em bé thức giấc."}]', '[{"phrase":"economic boom"},{"phrase":"baby boom"},{"phrase":"loud boom"}]', NULL, '/buːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/boo/boom_/boom__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 17, 'tale', 'câu chuyện; truyện kể', 'noun', '[{"en":"My grandmother used to tell us tales about her childhood.","vi":"Bà tôi thường kể cho chúng tôi nghe những câu chuyện về thời thơ ấu của bà."},{"en":"Every child in the village knows this old fairy tale.","vi":"Mọi đứa trẻ trong làng đều biết câu chuyện cổ tích xưa này."},{"en":"He came back from his trip with exciting tales of adventure.","vi":"Anh ấy trở về sau chuyến đi với những câu chuyện phiêu lưu thú vị."}]', '[{"phrase":"fairy tale"},{"phrase":"folk tale"},{"phrase":"tell a tale"}]', NULL, '/teɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tal/tale_/tale__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 18, 'democratic', 'dân chủ', 'adjective', '[{"en":"The club makes all its decisions in a democratic way.","vi":"Câu lạc bộ đưa ra mọi quyết định một cách dân chủ."},{"en":"Our class chose its leader through a democratic vote.","vi":"Lớp chúng tôi chọn lớp trưởng qua một cuộc bỏ phiếu dân chủ."},{"en":"Free elections are an important part of a democratic society.","vi":"Bầu cử tự do là một phần quan trọng của xã hội dân chủ."}]', '[{"phrase":"democratic society"},{"phrase":"democratic process"},{"phrase":"democratic country"}]', NULL, '/ˌdeməˈkrætɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dem/democ/democratic__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 19, 'maintenance', 'sự bảo trì; sự bảo dưỡng', 'noun', '[{"en":"The elevator is closed for maintenance until Friday.","vi":"Thang máy tạm ngừng hoạt động để bảo trì đến thứ Sáu."},{"en":"Old cars usually need more maintenance than new ones.","vi":"Xe cũ thường cần bảo dưỡng nhiều hơn xe mới."},{"en":"The maintenance team fixes any problems in the building.","vi":"Đội bảo trì sửa mọi sự cố trong tòa nhà."}]', '[{"phrase":"regular maintenance"},{"phrase":"routine maintenance"},{"phrase":"maintenance costs"}]', 'không đếm được', '/ˈmeɪntənəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mai/maint/maintenance__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 20, 'consequently', 'do đó; vì vậy', 'adverb', '[{"en":"He missed the bus and consequently arrived late for work.","vi":"Anh ấy lỡ chuyến xe buýt và vì vậy đến chỗ làm muộn."},{"en":"She studied hard and consequently passed all her exams.","vi":"Cô ấy học chăm chỉ và do đó đã đỗ tất cả các kỳ thi."},{"en":"Prices went up; consequently, fewer people bought new cars.","vi":"Giá cả tăng lên, do đó ít người mua ô tô mới hơn."}]', '[{"phrase":"and consequently"},{"phrase":"is consequently"}]', NULL, '/ˈkɑːnsɪkwentli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsequently__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 21, 'pot', 'nồi; chậu (cây); bình (trà, cà phê)', 'noun', '[{"en":"She cooked a big pot of soup for the whole family.","vi":"Cô ấy nấu một nồi súp lớn cho cả nhà."},{"en":"I planted some tomatoes in a pot on the balcony.","vi":"Tôi trồng vài cây cà chua trong chậu ngoài ban công."},{"en":"Let me make a fresh pot of coffee for our guests.","vi":"Để tôi pha một bình cà phê mới cho khách."}]', '[{"phrase":"pot of coffee"},{"phrase":"flower pot"},{"phrase":"cooking pot"}]', NULL, '/pɑːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pot/pot__/pot__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 22, 'cow', 'con bò (cái)', 'noun', '[{"en":"The farmer milks his cows early every morning.","vi":"Người nông dân vắt sữa bò vào sáng sớm mỗi ngày."},{"en":"We saw cows eating grass beside the road.","vi":"Chúng tôi thấy những con bò đang gặm cỏ bên đường."},{"en":"This cheese is made from cow''s milk.","vi":"Loại phô mai này được làm từ sữa bò."}]', '[{"phrase":"milk a cow"},{"phrase":"dairy cow"},{"phrase":"cow''s milk"}]', NULL, '/kaʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cow/cow__/cow__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 23, 'strengthen', 'làm mạnh thêm; củng cố, tăng cường', 'verb', '[{"en":"Swimming is a great way to strengthen your back muscles.","vi":"Bơi lội là cách tuyệt vời để làm khỏe cơ lưng."},{"en":"The trip helped strengthen the friendship between our two families.","vi":"Chuyến đi đã giúp củng cố tình bạn giữa hai gia đình chúng tôi."},{"en":"Workers strengthened the old bridge before the rainy season.","vi":"Công nhân đã gia cố cây cầu cũ trước mùa mưa."}]', '[{"phrase":"strengthen muscles"},{"phrase":"strengthen relationships"},{"phrase":"strengthen ties"}]', NULL, '/ˈstreŋkθn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stren/strengthen__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 24, 'whilst', 'trong khi; trong khi đó (đối lập)', 'conjunction', '[{"en":"Please wait here whilst I go and get the car.","vi":"Vui lòng đợi ở đây trong khi tôi đi lấy xe."},{"en":"She listened to music whilst doing her homework.","vi":"Cô ấy nghe nhạc trong khi làm bài tập về nhà."},{"en":"Some students prefer to study alone, whilst others like working in groups.","vi":"Một số sinh viên thích học một mình, trong khi những người khác thích học nhóm."}]', '[{"phrase":"whilst others"},{"phrase":"whilst waiting"}]', 'Anh-Anh, trang trọng hơn; Mỹ thường dùng while', '/waɪlst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whi/whils/whilst__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 25, 'constraint', 'sự hạn chế; sự ràng buộc', 'noun', '[{"en":"Because of time constraints, we can only answer three questions.","vi":"Vì hạn chế về thời gian, chúng tôi chỉ có thể trả lời ba câu hỏi."},{"en":"Budget constraints forced the school to cancel the trip.","vi":"Hạn chế về ngân sách buộc nhà trường phải hủy chuyến đi."},{"en":"Artists should be free to work without constraints.","vi":"Nghệ sĩ nên được tự do sáng tác mà không bị ràng buộc."}]', '[{"phrase":"time constraints"},{"phrase":"budget constraints"},{"phrase":"financial constraints"}]', NULL, '/kənˈstreɪnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstraint__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 26, 'fold', 'gấp, gập; khoanh (tay)', 'verb', '[{"en":"Please fold the towels and put them in the drawer.","vi":"Làm ơn gấp khăn rồi cất vào ngăn kéo."},{"en":"She folded the letter carefully and put it in an envelope.","vi":"Cô ấy cẩn thận gấp lá thư lại rồi cho vào phong bì."},{"en":"He stood by the door with his arms folded.","vi":"Anh ấy khoanh tay đứng cạnh cửa."}]', '[{"phrase":"fold clothes"},{"phrase":"fold your arms"},{"phrase":"fold in half"}]', NULL, '/fəʊld/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fol/fold_/fold__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 27, 'bin', 'thùng rác; thùng (đựng đồ)', 'noun', '[{"en":"Please throw your empty bottles in the recycling bin.","vi":"Vui lòng bỏ chai rỗng vào thùng rác tái chế."},{"en":"I forgot to take the bins out last night.","vi":"Tối qua tôi quên mang thùng rác ra ngoài."},{"en":"We keep rice in a large plastic bin in the kitchen.","vi":"Chúng tôi đựng gạo trong một cái thùng nhựa lớn ở bếp."}]', '[{"phrase":"recycling bin"},{"phrase":"rubbish bin"},{"phrase":"take the bins out"}]', 'Mỹ thường dùng trash can cho thùng rác', '/bɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bin/bin__/bin__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 28, 'undergo', 'trải qua (thay đổi, phẫu thuật, kiểm tra)', 'verb', '[{"en":"My father underwent surgery on his knee last month.","vi":"Tháng trước bố tôi đã trải qua ca phẫu thuật đầu gối."},{"en":"The city center is undergoing major changes this year.","vi":"Trung tâm thành phố đang trải qua những thay đổi lớn trong năm nay."},{"en":"All new cars must undergo strict safety tests.","vi":"Mọi ô tô mới đều phải trải qua các cuộc kiểm tra an toàn nghiêm ngặt."}]', '[{"phrase":"undergo surgery"},{"phrase":"undergo changes"},{"phrase":"undergo tests"},{"phrase":"undergo training"}]', 'undergo – underwent – undergone', '/ˌʌndərˈɡəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/und/under/undergo__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-02', 29, 'potentially', 'có khả năng; có tiềm năng', 'adverb', '[{"en":"This new medicine could potentially help millions of people.","vi":"Loại thuốc mới này có khả năng giúp được hàng triệu người."},{"en":"Driving in this weather is potentially dangerous.","vi":"Lái xe trong thời tiết này có thể gây nguy hiểm."},{"en":"The problem is small now but is potentially very serious.","vi":"Vấn đề hiện còn nhỏ nhưng có khả năng trở nên rất nghiêm trọng."}]', '[{"phrase":"potentially dangerous"},{"phrase":"potentially serious"},{"phrase":"potentially useful"}]', NULL, '/pəˈtenʃəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pot/poten/potentially__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-6-03', 'ngsl-6', 'Thông dụng 2.501–2.809 · Bộ 3', 'New General Service List, thứ hạng 2.501–2.809', '#3da9fc', 'BookOpen', 3);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 1, 'scope', 'phạm vi; cơ hội (để làm gì)', 'noun', '[{"en":"The project was much bigger in scope than we first expected.","vi":"Dự án có phạm vi lớn hơn nhiều so với dự tính ban đầu của chúng tôi."},{"en":"That question is outside the scope of today''s meeting.","vi":"Câu hỏi đó nằm ngoài phạm vi của cuộc họp hôm nay."},{"en":"There is still plenty of scope for improvement in your writing.","vi":"Bài viết của bạn vẫn còn nhiều chỗ để cải thiện."}]', '[{"phrase":"outside the scope of"},{"phrase":"beyond the scope of"},{"phrase":"scope for improvement"},{"phrase":"limited scope"}]', NULL, '/skəʊp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sco/scope/scope__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 2, 'pretend', 'giả vờ; giả làm', 'verb', '[{"en":"He pretended to be asleep when his mother came in.","vi":"Cậu ấy giả vờ ngủ khi mẹ bước vào."},{"en":"Please don''t pretend that you didn''t hear what I just said.","vi":"Làm ơn đừng giả vờ là bạn không nghe thấy những gì tôi vừa nói."},{"en":"The kids like to pretend they are pirates on a big ship.","vi":"Bọn trẻ thích giả làm cướp biển trên một con tàu lớn."}]', '[{"phrase":"pretend to be"},{"phrase":"pretend not to notice"},{"phrase":"just pretend"}]', NULL, '/prɪˈtend/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prete/pretend__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 3, 'diversity', 'sự đa dạng', 'noun', '[{"en":"The city is known for its cultural diversity and great food.","vi":"Thành phố này nổi tiếng với sự đa dạng văn hóa và đồ ăn ngon."},{"en":"We need more diversity in the team that makes these decisions.","vi":"Chúng ta cần sự đa dạng hơn trong nhóm đưa ra những quyết định này."},{"en":"This forest has an amazing diversity of plants and animals.","vi":"Khu rừng này có sự đa dạng đáng kinh ngạc về thực vật và động vật."}]', '[{"phrase":"cultural diversity"},{"phrase":"biological diversity"},{"phrase":"a diversity of"}]', NULL, '/daɪˈvɜːrsəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/div/diver/diversity__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 4, 'allege', 'cáo buộc; cho rằng (chưa có bằng chứng)', 'verb', '[{"en":"The report alleges that the company ignored basic safety rules.","vi":"Bản báo cáo cáo buộc rằng công ty đã phớt lờ các quy định an toàn cơ bản."},{"en":"She alleged that her manager had treated her unfairly.","vi":"Cô ấy cáo buộc rằng quản lý đã đối xử bất công với mình."},{"en":"He is alleged to have taken money from the club.","vi":"Anh ta bị cho là đã lấy tiền của câu lạc bộ."}]', '[{"phrase":"allege that"},{"phrase":"be alleged to have"}]', 'danh từ: allegation (lời cáo buộc)', '/əˈledʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/all/alleg/allege__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 5, 'pride', 'niềm tự hào; lòng tự trọng', 'noun', '[{"en":"She spoke about her children with obvious pride.","vi":"Bà ấy nói về các con với niềm tự hào lộ rõ."},{"en":"He takes great pride in keeping his garden tidy.","vi":"Ông ấy rất tự hào về việc giữ khu vườn luôn gọn gàng."},{"en":"His pride stopped him from asking his friends for help.","vi":"Lòng tự trọng khiến anh ấy không chịu nhờ bạn bè giúp đỡ."}]', '[{"phrase":"take pride in"},{"phrase":"great pride"},{"phrase":"a sense of pride"}]', 'tính từ: proud (tự hào)', '/praɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/pride/pride__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 6, 'intense', 'dữ dội, mãnh liệt; căng thẳng', 'adjective', '[{"en":"The heat in the desert was so intense that we stayed inside.","vi":"Cái nóng ở sa mạc gay gắt đến mức chúng tôi phải ở trong nhà."},{"en":"After weeks of intense training, she was ready for the race.","vi":"Sau nhiều tuần tập luyện cường độ cao, cô ấy đã sẵn sàng cho cuộc đua."},{"en":"The final minutes of the game were really intense.","vi":"Những phút cuối của trận đấu thật sự rất căng thẳng."}]', '[{"phrase":"intense heat"},{"phrase":"intense pressure"},{"phrase":"intense competition"},{"phrase":"intense training"}]', NULL, '/ɪnˈtens/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inten/intense__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 7, 'inquiry', 'cuộc điều tra; câu hỏi, yêu cầu thông tin', 'noun', '[{"en":"The airport has launched an inquiry into last week''s long delays.","vi":"Sân bay đã mở cuộc điều tra về tình trạng chậm trễ kéo dài vào tuần trước."},{"en":"The hotel received hundreds of inquiries about its summer offer.","vi":"Khách sạn nhận được hàng trăm yêu cầu hỏi thông tin về ưu đãi mùa hè."},{"en":"For further inquiries, please contact our customer service team.","vi":"Nếu có thắc mắc thêm, vui lòng liên hệ bộ phận chăm sóc khách hàng."}]', '[{"phrase":"launch an inquiry"},{"phrase":"an inquiry into"},{"phrase":"make inquiries"},{"phrase":"public inquiry"}]', 'Anh thường viết: enquiry', '/ˈɪnkwəri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/enq/enqui/enquiry__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 8, 'resign', 'từ chức; xin nghỉ việc', 'verb', '[{"en":"She resigned from her job to start her own business.","vi":"Cô ấy xin nghỉ việc để tự kinh doanh."},{"en":"The team''s coach resigned after a very poor season.","vi":"Huấn luyện viên của đội đã từ chức sau một mùa giải rất tệ."},{"en":"He decided to resign as president of the tennis club.","vi":"Ông ấy quyết định từ chức chủ tịch câu lạc bộ quần vợt."}]', '[{"phrase":"resign from a job"},{"phrase":"resign as"},{"phrase":"decide to resign"}]', 'resign from + công việc; resign as + chức vụ', '/rɪˈzaɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resig/resign__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 9, 'craft', 'nghề thủ công; tay nghề', 'noun', '[{"en":"The village is famous for traditional crafts like weaving and pottery.","vi":"Ngôi làng nổi tiếng với các nghề thủ công truyền thống như dệt vải và làm gốm."},{"en":"My daughter loves arts and crafts, especially painting.","vi":"Con gái tôi rất thích thủ công mỹ thuật, nhất là vẽ tranh."},{"en":"Every good writer spends years improving their craft.","vi":"Nhà văn giỏi nào cũng dành nhiều năm để trau dồi tay nghề của mình."}]', '[{"phrase":"traditional crafts"},{"phrase":"arts and crafts"},{"phrase":"craft fair"}]', NULL, '/kræft/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cra/craft/craft__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 10, 'strict', 'nghiêm khắc; nghiêm ngặt', 'adjective', '[{"en":"My parents were very strict about bedtime when I was young.","vi":"Hồi tôi còn nhỏ, bố mẹ rất nghiêm khắc về giờ đi ngủ."},{"en":"The school has strict rules about using phones in class.","vi":"Trường có quy định nghiêm ngặt về việc dùng điện thoại trong lớp."},{"en":"She follows a strict diet before every competition.","vi":"Cô ấy theo một chế độ ăn kiêng nghiêm ngặt trước mỗi cuộc thi."}]', '[{"phrase":"strict rules"},{"phrase":"strict parents"},{"phrase":"strict diet"},{"phrase":"be strict about"}]', NULL, '/strɪkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stric/strict__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 11, 'concrete', 'cụ thể; bằng bê tông', 'adjective', '[{"en":"Can you give me a concrete example of what you mean?","vi":"Bạn có thể cho tôi một ví dụ cụ thể về ý bạn muốn nói không?"},{"en":"The meeting ended without any concrete plans for next year.","vi":"Cuộc họp kết thúc mà không có kế hoạch cụ thể nào cho năm sau."},{"en":"The kids sat on the concrete steps outside the library.","vi":"Bọn trẻ ngồi trên những bậc thềm bê tông bên ngoài thư viện."}]', '[{"phrase":"concrete example"},{"phrase":"concrete evidence"},{"phrase":"concrete plans"},{"phrase":"concrete floor"}]', 'danh từ: concrete (bê tông)', '/ˈkɑːnkriːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconcrete__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 12, 'shell', 'vỏ (sò, trứng, hạt); mai (rùa)', 'noun', '[{"en":"We collected shells on the beach all afternoon.","vi":"Chúng tôi nhặt vỏ sò trên bãi biển cả buổi chiều."},{"en":"Crack the eggs gently so that no shell falls into the bowl.","vi":"Đập trứng nhẹ tay để vỏ không rơi vào bát."},{"en":"The turtle pulled its head back into its shell.","vi":"Con rùa rụt đầu vào trong mai."}]', '[{"phrase":"collect shells"},{"phrase":"hard shell"},{"phrase":"come out of your shell"}]', NULL, '/ʃel/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/she/shell/shell__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 13, 'damn', 'chết tiệt; (nhấn mạnh) cực kỳ', 'exclamation', '[{"en":"Damn, I left my keys at the office again!","vi":"Chết tiệt, tôi lại để quên chìa khóa ở văn phòng rồi!"},{"en":"That was a damn good meal, thank you.","vi":"Bữa ăn đó ngon cực kỳ, cảm ơn bạn."},{"en":"Damn, we just missed the last bus home.","vi":"Chết tiệt, chúng ta vừa lỡ chuyến xe buýt cuối cùng về nhà rồi."}]', '[{"phrase":"damn it"},{"phrase":"damn good"},{"phrase":"not give a damn"}]', 'từ thông tục, hơi thô – tránh dùng khi trang trọng', '/dæm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dam/damn_/damn__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 14, 'distinct', 'khác biệt, riêng biệt; rõ rệt', 'adjective', '[{"en":"Their new album is quite distinct from their earlier work.","vi":"Album mới của họ khá khác biệt so với các sản phẩm trước đây."},{"en":"There was a distinct smell of smoke in the kitchen.","vi":"Trong bếp có mùi khói rõ rệt."},{"en":"Each region of the country has its own distinct style of cooking.","vi":"Mỗi vùng của đất nước có phong cách nấu ăn riêng biệt."}]', '[{"phrase":"distinct from"},{"phrase":"a distinct possibility"},{"phrase":"a distinct advantage"}]', NULL, '/dɪˈstɪŋkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disti/distinct__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 15, 'humor', 'sự hài hước', 'noun', '[{"en":"My grandfather has a great sense of humor.","vi":"Ông tôi rất có khiếu hài hước."},{"en":"She used humor to help the nervous students relax.","vi":"Cô ấy dùng sự hài hước để giúp các học sinh đang lo lắng thấy thoải mái."},{"en":"I didn''t understand the humor in his jokes at all.","vi":"Tôi hoàn toàn không hiểu những câu đùa của anh ấy hài hước ở chỗ nào."}]', '[{"phrase":"sense of humor"},{"phrase":"good humor"},{"phrase":"dry humor"}]', 'Mỹ: humor · Anh: humour', '/ˈhjuːmər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hum/humou/humour__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 16, 'limitation', 'sự hạn chế; giới hạn', 'noun', '[{"en":"Every method has its limitations, so choose carefully.","vi":"Phương pháp nào cũng có những hạn chế, nên hãy chọn cẩn thận."},{"en":"It''s important to know your own limitations.","vi":"Điều quan trọng là phải biết giới hạn của bản thân."},{"en":"Because of time limitations, we couldn''t visit every museum in the city.","vi":"Vì hạn chế về thời gian, chúng tôi không thể tham quan mọi bảo tàng trong thành phố."}]', '[{"phrase":"have limitations"},{"phrase":"time limitations"},{"phrase":"know your limitations"},{"phrase":"physical limitations"}]', NULL, '/ˌlɪmɪˈteɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lim/limit/limitation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 17, 'indication', 'dấu hiệu', 'noun', '[{"en":"There is no indication that the weather will improve soon.","vi":"Không có dấu hiệu nào cho thấy thời tiết sẽ sớm tốt lên."},{"en":"His smile was a clear indication that he liked the gift.","vi":"Nụ cười của anh ấy là dấu hiệu rõ ràng cho thấy anh ấy thích món quà."},{"en":"Did she give any indication of when she would be back?","vi":"Cô ấy có cho biết khi nào sẽ quay lại không?"}]', '[{"phrase":"a clear indication"},{"phrase":"give an indication"},{"phrase":"no indication that"},{"phrase":"an indication of"}]', NULL, '/ˌɪndɪˈkeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indic/indication__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 18, 'stability', 'sự ổn định; sự vững chắc', 'noun', '[{"en":"Children need stability and routine to feel safe.","vi":"Trẻ em cần sự ổn định và nề nếp để cảm thấy an toàn."},{"en":"After years of moving around, she finally found financial stability.","vi":"Sau nhiều năm chuyển chỗ liên tục, cuối cùng cô ấy cũng ổn định được về tài chính."},{"en":"Wider tires give the bike more stability on rough roads.","vi":"Lốp rộng hơn giúp xe đạp vững hơn trên đường gồ ghề."}]', '[{"phrase":"financial stability"},{"phrase":"economic stability"},{"phrase":"emotional stability"}]', NULL, '/stəˈbɪləti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stabi/stability__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 19, 'wise', 'khôn ngoan, sáng suốt; thông thái', 'adjective', '[{"en":"My grandmother was a wise woman who always gave good advice.","vi":"Bà tôi là một người phụ nữ thông thái, luôn đưa ra những lời khuyên hay."},{"en":"It would be wise to book your tickets early.","vi":"Đặt vé sớm sẽ là điều khôn ngoan."},{"en":"I think you made a wise decision to change jobs.","vi":"Tôi nghĩ bạn đã quyết định sáng suốt khi đổi việc."}]', '[{"phrase":"a wise decision"},{"phrase":"a wise choice"},{"phrase":"it would be wise to"},{"phrase":"wise words"}]', NULL, '/waɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wis/wise_/wise__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 20, 'neglect', 'bỏ bê, sao nhãng; lơ là', 'verb', '[{"en":"He was so busy with work that he neglected his health.","vi":"Anh ấy bận công việc đến mức bỏ bê sức khỏe."},{"en":"The old house had been neglected for many years.","vi":"Ngôi nhà cũ đã bị bỏ mặc không ai chăm sóc suốt nhiều năm."},{"en":"Don''t neglect your studies just because the exams are far away.","vi":"Đừng lơ là việc học chỉ vì kỳ thi còn xa."}]', '[{"phrase":"neglect your health"},{"phrase":"badly neglected"},{"phrase":"neglect your duties"}]', NULL, '/nɪˈɡlekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/neg/negle/neglect__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 21, 'compose', 'sáng tác; soạn (thư, email); gồm có', 'verb', '[{"en":"She composed her first song when she was only twelve.","vi":"Cô ấy sáng tác bài hát đầu tiên khi mới mười hai tuổi."},{"en":"I spent an hour composing a polite email to my landlord.","vi":"Tôi mất một tiếng để soạn một email lịch sự gửi chủ nhà."},{"en":"The team is composed of students from five different countries.","vi":"Đội gồm các sinh viên đến từ năm quốc gia khác nhau."}]', '[{"phrase":"compose music"},{"phrase":"compose a letter"},{"phrase":"be composed of"}]', 'be composed of = consist of: gồm có', '/kəmˈpəʊz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compo/compose__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 22, 'jail', 'nhà tù', 'noun', '[{"en":"He spent two years in jail for stealing cars.","vi":"Anh ta đã ngồi tù hai năm vì tội trộm xe hơi."},{"en":"The movie is about a man who escapes from jail.","vi":"Bộ phim kể về một người đàn ông vượt ngục."},{"en":"The judge sent him to jail for six months.","vi":"Thẩm phán đã tuyên phạt anh ta sáu tháng tù."}]', '[{"phrase":"go to jail"},{"phrase":"in jail"},{"phrase":"escape from jail"},{"phrase":"send someone to jail"}]', NULL, '/dʒeɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jai/jail_/jail__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 23, 'shelter', 'nơi trú ẩn; chỗ ở', 'noun', '[{"en":"We took shelter under a tree when the rain started.","vi":"Chúng tôi trú dưới một gốc cây khi trời bắt đầu mưa."},{"en":"She adopted her cat from an animal shelter.","vi":"Cô ấy nhận nuôi con mèo từ một trại cứu hộ động vật."},{"en":"Food, water and shelter are basic human needs.","vi":"Thức ăn, nước uống và chỗ ở là những nhu cầu cơ bản của con người."}]', '[{"phrase":"take shelter"},{"phrase":"animal shelter"},{"phrase":"seek shelter"},{"phrase":"food and shelter"}]', NULL, '/ˈʃeltər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/she/shelt/shelter__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 24, 'mere', 'chỉ, chỉ là', 'adjective', '[{"en":"The shop is a mere five minutes from our house.","vi":"Cửa hàng chỉ cách nhà chúng tôi năm phút."},{"en":"The mere thought of flying makes me nervous.","vi":"Chỉ nghĩ đến việc đi máy bay thôi là tôi đã thấy lo."},{"en":"He was a mere child when he moved abroad.","vi":"Cậu ấy chỉ là một đứa trẻ khi chuyển ra nước ngoài."}]', '[{"phrase":"the mere thought of"},{"phrase":"a mere formality"},{"phrase":"a mere fraction"}]', 'chỉ đứng trước danh từ; trạng từ: merely', '/mɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mer/mere_/mere__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 25, 'carbon', 'cacbon', 'noun', '[{"en":"Planting trees helps remove carbon from the air.","vi":"Trồng cây giúp loại bỏ cacbon khỏi không khí."},{"en":"Our company wants to reduce its carbon emissions by half.","vi":"Công ty chúng tôi muốn giảm một nửa lượng khí thải cacbon."},{"en":"Did you know that diamonds are made almost entirely of carbon?","vi":"Bạn có biết kim cương được tạo thành gần như hoàn toàn từ cacbon không?"}]', '[{"phrase":"carbon dioxide"},{"phrase":"carbon emissions"},{"phrase":"carbon footprint"}]', NULL, '/ˈkɑːrbən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/car/carbo/carbon__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 26, 'regulate', 'điều chỉnh; quản lý (bằng quy định)', 'verb', '[{"en":"This device regulates the temperature in the room.","vi":"Thiết bị này điều chỉnh nhiệt độ trong phòng."},{"en":"The city strictly regulates where people are allowed to park.","vi":"Thành phố quy định chặt chẽ những nơi người dân được phép đỗ xe."},{"en":"Banks are closely regulated to protect their customers'' money.","vi":"Các ngân hàng được quản lý chặt chẽ để bảo vệ tiền của khách hàng."}]', '[{"phrase":"regulate temperature"},{"phrase":"strictly regulate"},{"phrase":"closely regulated"}]', NULL, '/ˈreɡjuleɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regul/regulate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 27, 'cheese', 'phô mai', 'noun', '[{"en":"Would you like some cheese on your pasta?","vi":"Bạn có muốn thêm ít phô mai lên mì Ý không?"},{"en":"This shop sells more than fifty kinds of cheese.","vi":"Cửa hàng này bán hơn năm mươi loại phô mai."},{"en":"I made a cheese sandwich for lunch today.","vi":"Hôm nay tôi làm một chiếc bánh mì kẹp phô mai cho bữa trưa."}]', '[{"phrase":"cheese sandwich"},{"phrase":"grated cheese"},{"phrase":"a slice of cheese"},{"phrase":"cream cheese"}]', 'thường không đếm được: some cheese, a slice of cheese', '/tʃiːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/che/chees/cheese__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 28, 'trigger', 'gây ra; kích hoạt', 'verb', '[{"en":"Strong smells can trigger headaches in some people.","vi":"Mùi nồng có thể gây đau đầu ở một số người."},{"en":"Someone opened a window and triggered the alarm.","vi":"Ai đó đã mở cửa sổ và làm kích hoạt chuông báo động."},{"en":"His comment triggered a long argument between the two teams.","vi":"Lời nhận xét của anh ấy đã gây ra một cuộc tranh cãi dài giữa hai đội."}]', '[{"phrase":"trigger an alarm"},{"phrase":"trigger a reaction"},{"phrase":"trigger memories"}]', NULL, '/ˈtrɪɡər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tri/trigg/trigger__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-03', 29, 'pipe', 'ống (nước, khí); tẩu thuốc', 'noun', '[{"en":"A pipe burst in the kitchen and flooded the floor.","vi":"Một đường ống trong bếp bị vỡ khiến sàn nhà ngập nước."},{"en":"Water flows through these pipes to every house in the village.","vi":"Nước chảy qua những đường ống này đến từng ngôi nhà trong làng."},{"en":"My grandfather used to smoke a pipe after dinner.","vi":"Ông tôi từng hút tẩu sau bữa tối."}]', '[{"phrase":"water pipe"},{"phrase":"burst pipe"},{"phrase":"gas pipe"},{"phrase":"smoke a pipe"}]', NULL, '/paɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pip/pipe_/pipe__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-6-04', 'ngsl-6', 'Thông dụng 2.501–2.809 · Bộ 4', 'New General Service List, thứ hạng 2.501–2.809', '#3da9fc', 'BookOpen', 4);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 1, 'destruction', 'sự phá hủy; sự tàn phá', 'noun', '[{"en":"The storm caused terrible destruction along the coast last year.","vi":"Cơn bão năm ngoái đã gây ra sự tàn phá khủng khiếp dọc bờ biển."},{"en":"Many animals are losing their homes because of the destruction of forests.","vi":"Nhiều loài động vật đang mất nơi sống vì rừng bị phá hủy."},{"en":"We watched a film about the destruction of an ancient city.","vi":"Chúng tôi đã xem một bộ phim về sự hủy diệt của một thành phố cổ."}]', '[{"phrase":"cause destruction"},{"phrase":"the destruction of"},{"phrase":"widespread destruction"},{"phrase":"environmental destruction"}]', 'không đếm được', '/dɪˈstrʌkʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/destr/destruction__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 2, 'guitar', 'đàn ghi-ta', 'noun', '[{"en":"My brother taught himself to play the guitar last summer.","vi":"Anh trai tôi đã tự học chơi ghi-ta vào mùa hè năm ngoái."},{"en":"She sat by the fire and played her guitar for us.","vi":"Cô ấy ngồi cạnh đống lửa và chơi ghi-ta cho chúng tôi nghe."},{"en":"Do you know where I can buy a cheap guitar?","vi":"Bạn có biết chỗ nào mua được đàn ghi-ta rẻ không?"}]', '[{"phrase":"play the guitar"},{"phrase":"electric guitar"},{"phrase":"acoustic guitar"},{"phrase":"guitar lesson"}]', NULL, '/ɡɪˈtɑːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gui/guita/guitar__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 3, 'flag', 'lá cờ', 'noun', '[{"en":"The children waved small flags as the runners went past.","vi":"Bọn trẻ vẫy những lá cờ nhỏ khi các vận động viên chạy ngang qua."},{"en":"A red flag on the beach means it is not safe to swim.","vi":"Cờ đỏ trên bãi biển nghĩa là bơi không an toàn."},{"en":"Every morning they raise the flag in front of the school.","vi":"Mỗi sáng họ kéo cờ trước cổng trường."}]', '[{"phrase":"national flag"},{"phrase":"wave a flag"},{"phrase":"raise a flag"},{"phrase":"red flag"}]', NULL, '/flæɡ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fla/flag_/flag__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 4, 'piano', 'đàn piano; dương cầm', 'noun', '[{"en":"My daughter has been learning to play the piano for three years.","vi":"Con gái tôi đã học chơi piano được ba năm."},{"en":"There is an old piano in the corner of the living room.","vi":"Có một cây đàn piano cũ ở góc phòng khách."},{"en":"He practices the piano for an hour every evening after dinner.","vi":"Mỗi tối sau bữa ăn, anh ấy tập đàn piano một tiếng."}]', '[{"phrase":"play the piano"},{"phrase":"piano lesson"},{"phrase":"piano teacher"},{"phrase":"grand piano"}]', NULL, '/piˈænəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pia/piano/piano__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 5, 'magic', 'phép thuật; ảo thuật; sự kỳ diệu', 'noun', '[{"en":"In the story, the old woman uses magic to turn him into a frog.","vi":"Trong câu chuyện, bà lão dùng phép thuật biến anh ta thành một con ếch."},{"en":"My uncle did a few magic tricks at the birthday party.","vi":"Chú tôi đã biểu diễn vài trò ảo thuật ở bữa tiệc sinh nhật."},{"en":"Nobody can forget the magic of seeing snow for the first time.","vi":"Không ai quên được sự kỳ diệu của lần đầu tiên nhìn thấy tuyết."}]', '[{"phrase":"magic trick"},{"phrase":"black magic"},{"phrase":"like magic"},{"phrase":"the magic of"}]', 'không đếm được', '/ˈmædʒɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mag/magic/magic__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 6, 'mystery', 'điều bí ẩn; truyện trinh thám', 'noun', '[{"en":"Where my keys went is still a complete mystery to me.","vi":"Chìa khóa của tôi biến đi đâu vẫn là một điều hoàn toàn bí ẩn với tôi."},{"en":"Scientists are trying to solve the mystery of how the lake formed.","vi":"Các nhà khoa học đang cố giải đáp bí ẩn về việc hồ này hình thành như thế nào."},{"en":"She likes to read a good mystery before going to bed.","vi":"Cô ấy thích đọc một cuốn truyện trinh thám hay trước khi đi ngủ."}]', '[{"phrase":"solve a mystery"},{"phrase":"remain a mystery"},{"phrase":"complete mystery"},{"phrase":"mystery novel"}]', NULL, '/ˈmɪstəri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mys/myste/mystery__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 7, 'ski', 'trượt tuyết', 'verb', '[{"en":"We go skiing in the mountains every winter with our cousins.","vi":"Mùa đông nào chúng tôi cũng đi trượt tuyết trên núi cùng anh em họ."},{"en":"I learned to ski when I was about ten years old.","vi":"Tôi học trượt tuyết khi khoảng mười tuổi."},{"en":"She skied down the hill much faster than the rest of us.","vi":"Cô ấy trượt tuyết xuống đồi nhanh hơn hẳn những người còn lại."}]', '[{"phrase":"go skiing"},{"phrase":"learn to ski"},{"phrase":"ski resort"},{"phrase":"ski slope"}]', NULL, '/skiː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ski/ski__/ski__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 8, 'whisper', 'thì thầm; nói nhỏ', 'verb', '[{"en":"She leaned over and whispered something in my ear.","vi":"Cô ấy nghiêng người sang và thì thầm điều gì đó vào tai tôi."},{"en":"Please whisper if you need to talk during the movie.","vi":"Nếu cần nói chuyện trong lúc xem phim thì làm ơn nói nhỏ thôi."},{"en":"The two girls were whispering and laughing at the back of the class.","vi":"Hai cô bé đang thì thầm và cười khúc khích ở cuối lớp."}]', '[{"phrase":"whisper in someone''s ear"},{"phrase":"whisper softly"},{"phrase":"whisper to someone"}]', NULL, '/ˈwɪspər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whi/whisp/whisper__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 9, 'rear', 'phía sau; đằng sau', 'noun', '[{"en":"Passengers should leave the bus through the door at the rear.","vi":"Hành khách nên xuống xe buýt bằng cửa phía sau."},{"en":"There is a small garden at the rear of the house.","vi":"Có một khu vườn nhỏ ở phía sau ngôi nhà."},{"en":"Someone hit the rear of my car while I was parked.","vi":"Có người đã tông vào đuôi xe tôi khi tôi đang đỗ xe."}]', '[{"phrase":"at the rear"},{"phrase":"the rear of"},{"phrase":"rear window"},{"phrase":"rear seat"}]', 'Cũng là tính từ: rear door (cửa sau)', '/rɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/rear_/rear__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 10, 'menu', 'thực đơn; menu (máy tính)', 'noun', '[{"en":"Could we have a look at the menu, please?","vi":"Cho chúng tôi xem thực đơn được không ạ?"},{"en":"There are several vegetarian dishes on the menu tonight.","vi":"Tối nay trong thực đơn có vài món chay."},{"en":"Click the menu at the top of the screen to save your file.","vi":"Nhấp vào menu ở đầu màn hình để lưu tệp của bạn."}]', '[{"phrase":"on the menu"},{"phrase":"look at the menu"},{"phrase":"set menu"},{"phrase":"main menu"}]', NULL, '/ˈmenjuː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/men/menu_/menu__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 11, 'species', 'loài', 'noun', '[{"en":"Many species of birds live in this part of the forest.","vi":"Nhiều loài chim sống ở khu vực này của khu rừng."},{"en":"Scientists have discovered a new species of frog in the mountains.","vi":"Các nhà khoa học đã phát hiện một loài ếch mới trên núi."},{"en":"Some plant species are disappearing because the climate is changing.","vi":"Một số loài thực vật đang biến mất vì khí hậu đang thay đổi."}]', '[{"phrase":"endangered species"},{"phrase":"species of"},{"phrase":"animal species"},{"phrase":"new species"}]', 'Số ít và số nhiều giống nhau: species', '/ˈspiːʃiːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speci/species__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 12, 'moon', 'mặt trăng', 'noun', '[{"en":"The moon was so bright that we could see the path clearly.","vi":"Mặt trăng sáng đến mức chúng tôi nhìn rõ con đường."},{"en":"Tonight there will be a full moon over the city.","vi":"Tối nay sẽ có trăng tròn trên bầu trời thành phố."},{"en":"Do you remember when people first walked on the moon?","vi":"Bạn có nhớ lần đầu tiên con người đặt chân lên mặt trăng không?"}]', '[{"phrase":"full moon"},{"phrase":"new moon"},{"phrase":"the moon rises"},{"phrase":"on the moon"}]', NULL, '/muːn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/moo/moon_/moon__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 13, 'presumably', 'có lẽ; chắc là', 'adverb', '[{"en":"The office is dark, so presumably everyone has already gone home.","vi":"Văn phòng tối om, nên chắc là mọi người đã về nhà cả rồi."},{"en":"Presumably the train is late because of the heavy snow.","vi":"Có lẽ tàu bị trễ vì tuyết rơi dày."},{"en":"He didn''t answer, presumably because he was still asleep.","vi":"Anh ấy không trả lời, có lẽ vì vẫn còn đang ngủ."}]', '[{"phrase":"presumably because"},{"phrase":"presumably not"}]', NULL, '/prɪˈzuːməbli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/presu/presumably__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 14, 'bless', 'ban phước; phù hộ; may mắn có (be blessed with)', 'verb', '[{"en":"\"Bless you!\" she said when I sneezed for the third time.","vi":"Khi tôi hắt xì lần thứ ba, cô ấy nói: \"Bless you!\" (chúc sức khỏe)."},{"en":"We feel truly blessed to have such kind and helpful neighbors.","vi":"Chúng tôi cảm thấy thật may mắn khi có những người hàng xóm tốt bụng và hay giúp đỡ như vậy."},{"en":"My grandfather was blessed with good health until his nineties.","vi":"Ông tôi may mắn có sức khỏe tốt cho đến tận tuổi chín mươi."}]', '[{"phrase":"bless you"},{"phrase":"be blessed with"},{"phrase":"feel blessed"}]', 'Nói "Bless you!" khi ai đó hắt xì', '/bles/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/ble/bless/bless__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 15, 'airline', 'hãng hàng không', 'noun', '[{"en":"Which airline are you flying with to Singapore next week?","vi":"Tuần sau bạn bay đi Singapore bằng hãng hàng không nào?"},{"en":"The airline lost my suitcase, so I had no clean clothes.","vi":"Hãng hàng không làm thất lạc vali của tôi nên tôi không có quần áo sạch."},{"en":"My sister works as a pilot for a small airline.","vi":"Chị gái tôi làm phi công cho một hãng hàng không nhỏ."}]', '[{"phrase":"airline ticket"},{"phrase":"budget airline"},{"phrase":"airline industry"},{"phrase":"airline passenger"}]', NULL, '/ˈerlaɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/air/airli/airline__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 16, 'amendment', 'sự sửa đổi; bản sửa đổi (luật, văn bản)', 'noun', '[{"en":"The committee made a small amendment to the contract before signing it.","vi":"Ủy ban đã sửa đổi nhỏ bản hợp đồng trước khi ký."},{"en":"Parliament voted to pass the amendment after a long debate.","vi":"Quốc hội đã bỏ phiếu thông qua bản sửa đổi sau một cuộc tranh luận dài."},{"en":"Please send any amendments to the report by Friday.","vi":"Vui lòng gửi mọi chỉnh sửa cho bản báo cáo trước thứ Sáu."}]', '[{"phrase":"make an amendment"},{"phrase":"pass an amendment"},{"phrase":"propose an amendment"},{"phrase":"amendment to"}]', NULL, '/əˈmendmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ame/amend/amendment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 17, 'grandmother', 'bà (nội, ngoại)', 'noun', '[{"en":"My grandmother taught me how to cook this soup.","vi":"Bà tôi đã dạy tôi cách nấu món canh này."},{"en":"We visit our grandmother in the countryside every summer.","vi":"Mùa hè nào chúng tôi cũng về quê thăm bà."},{"en":"Her grandmother is ninety but still walks to the market every day.","vi":"Bà của cô ấy đã chín mươi tuổi nhưng ngày nào cũng vẫn đi bộ ra chợ."}]', '[{"phrase":"visit your grandmother"},{"phrase":"great-grandmother"},{"phrase":"grandmother''s house"}]', NULL, '/ˈɡrænmʌðər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grand/grandmother__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 18, 'jury', 'bồi thẩm đoàn; ban giám khảo', 'noun', '[{"en":"After two days, the jury found the man not guilty.","vi":"Sau hai ngày, bồi thẩm đoàn tuyên bố người đàn ông vô tội."},{"en":"The jury took several hours to reach a decision.","vi":"Bồi thẩm đoàn mất vài tiếng để đưa ra quyết định."},{"en":"A jury of famous chefs chose the best dish in the competition.","vi":"Một ban giám khảo gồm các đầu bếp nổi tiếng đã chọn ra món ăn ngon nhất cuộc thi."}]', '[{"phrase":"jury trial"},{"phrase":"serve on a jury"},{"phrase":"the jury found"},{"phrase":"jury member"}]', NULL, '/ˈdʒʊri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jur/jury_/jury__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 19, 'cooperation', 'sự hợp tác', 'noun', '[{"en":"Thank you for your cooperation during the building repairs.","vi":"Cảm ơn sự hợp tác của quý vị trong thời gian sửa chữa tòa nhà."},{"en":"The project was a success thanks to close cooperation between the two teams.","vi":"Dự án thành công nhờ sự hợp tác chặt chẽ giữa hai nhóm."},{"en":"Both countries have agreed to increase cooperation on trade.","vi":"Hai nước đã đồng ý tăng cường hợp tác về thương mại."}]', '[{"phrase":"close cooperation"},{"phrase":"cooperation between"},{"phrase":"in cooperation with"},{"phrase":"international cooperation"}]', 'không đếm được', '/kəʊˌɑːpəˈreɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coo/coope/cooperation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 20, 'civilian', 'thường dân; dân thường', 'noun', '[{"en":"The new sports center is open to both soldiers and civilians.","vi":"Trung tâm thể thao mới mở cửa cho cả quân nhân lẫn dân thường."},{"en":"My father was a soldier, but he became a civilian again at forty.","vi":"Bố tôi từng là quân nhân, nhưng ông trở lại làm dân thường ở tuổi bốn mươi."},{"en":"Civilians are not allowed to enter the military base without a pass.","vi":"Dân thường không được vào căn cứ quân sự nếu không có giấy phép."}]', '[{"phrase":"civilian life"},{"phrase":"civilian population"},{"phrase":"protect civilians"}]', NULL, '/səˈvɪliən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/civ/civil/civilian__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 21, 'composition', 'thành phần; bản nhạc, sáng tác; bài luận', 'noun', '[{"en":"The composition of the team has changed a lot this year.","vi":"Thành phần của đội đã thay đổi nhiều trong năm nay."},{"en":"She played one of her own compositions at the concert.","vi":"Cô ấy đã chơi một trong những sáng tác của chính mình tại buổi hòa nhạc."},{"en":"Our teacher asked us to write a short composition about our summer.","vi":"Cô giáo yêu cầu chúng tôi viết một bài luận ngắn về mùa hè của mình."}]', '[{"phrase":"the composition of"},{"phrase":"musical composition"},{"phrase":"chemical composition"},{"phrase":"write a composition"}]', NULL, '/ˌkɑːmpəˈzɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compo/composition__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 22, 'coin', 'đồng xu', 'noun', '[{"en":"I need some coins for the parking machine.","vi":"Tôi cần vài đồng xu để trả tiền ở máy đỗ xe."},{"en":"Let''s toss a coin to decide who goes first.","vi":"Mình tung đồng xu để quyết định ai đi trước nhé."},{"en":"My grandfather has collected old coins for most of his life.","vi":"Ông tôi đã sưu tầm tiền xu cổ gần như cả đời."}]', '[{"phrase":"toss a coin"},{"phrase":"gold coin"},{"phrase":"collect coins"},{"phrase":"coin collection"}]', NULL, '/kɔɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coi/coin_/coin__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 23, 'regardless', 'bất kể; dù sao đi nữa', 'adverb', '[{"en":"Everyone can join the club regardless of age.","vi":"Ai cũng có thể tham gia câu lạc bộ, bất kể tuổi tác."},{"en":"It was raining hard, but we went for our walk regardless.","vi":"Trời mưa to nhưng dù sao chúng tôi vẫn đi dạo."},{"en":"Regardless of what happens, I will always support you.","vi":"Dù có chuyện gì xảy ra, tôi vẫn luôn ủng hộ bạn."}]', '[{"phrase":"regardless of"},{"phrase":"regardless of age"},{"phrase":"regardless of cost"}]', 'Thường đi với giới từ: regardless of + danh từ', '/rɪˈɡɑːrdləs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regar/regardless__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 24, 'scan', 'quét (máy); đọc lướt; nhìn kỹ khắp lượt', 'verb', '[{"en":"Could you scan these documents and email them to me?","vi":"Bạn có thể scan những tài liệu này rồi gửi email cho tôi không?"},{"en":"I quickly scanned the newspaper for news about the match.","vi":"Tôi đọc lướt nhanh tờ báo để tìm tin về trận đấu."},{"en":"She scanned the crowd, looking for her friend''s face.","vi":"Cô ấy đưa mắt nhìn khắp đám đông, tìm khuôn mặt của người bạn."}]', '[{"phrase":"scan a document"},{"phrase":"scan the horizon"},{"phrase":"scan the crowd"},{"phrase":"quickly scan"}]', 'scan – scanned – scanned', '/skæn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sca/scan_/scan__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 25, 'bunch', 'chùm; bó; nhóm (người)', 'noun', '[{"en":"He bought a bunch of flowers for his wife''s birthday.","vi":"Anh ấy mua một bó hoa nhân sinh nhật vợ."},{"en":"Could you get a bunch of bananas on your way home?","vi":"Trên đường về bạn mua giúp một nải chuối được không?"},{"en":"My new classmates are a really friendly bunch.","vi":"Các bạn cùng lớp mới của tôi là một nhóm người rất thân thiện."}]', '[{"phrase":"a bunch of flowers"},{"phrase":"a bunch of keys"},{"phrase":"a bunch of grapes"},{"phrase":"a whole bunch of"}]', 'Văn nói: a bunch of = nhiều', '/bʌntʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bun/bunch/bunch__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 26, 'racial', '(thuộc) chủng tộc', 'adjective', '[{"en":"The school welcomes students from many different racial backgrounds.","vi":"Trường chào đón học sinh đến từ nhiều nguồn gốc chủng tộc khác nhau."},{"en":"Racial discrimination at work is against the law in many countries.","vi":"Ở nhiều nước, phân biệt chủng tộc nơi làm việc là vi phạm pháp luật."},{"en":"The company wants to improve racial equality in its hiring.","vi":"Công ty muốn cải thiện sự bình đẳng chủng tộc trong việc tuyển dụng."}]', '[{"phrase":"racial discrimination"},{"phrase":"racial equality"},{"phrase":"racial background"},{"phrase":"racial groups"}]', NULL, '/ˈreɪʃl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rac/racia/racial__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 27, 'greet', 'chào; đón chào', 'verb', '[{"en":"The hotel manager greeted us warmly at the front door.","vi":"Quản lý khách sạn đã niềm nở chào đón chúng tôi ở cửa chính."},{"en":"Our dog always greets me when I get home from work.","vi":"Con chó nhà tôi lúc nào cũng ra chào khi tôi đi làm về."},{"en":"In some countries, people greet each other with a kiss on the cheek.","vi":"Ở một số nước, mọi người chào nhau bằng một nụ hôn lên má."}]', '[{"phrase":"greet someone warmly"},{"phrase":"greet each other"},{"phrase":"greet guests"},{"phrase":"be greeted with"}]', NULL, '/ɡriːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gre/greet/greet__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 28, 'hopefully', 'hy vọng là; mong là', 'adverb', '[{"en":"Hopefully the weather will be better tomorrow.","vi":"Hy vọng là ngày mai thời tiết sẽ đẹp hơn."},{"en":"I''m leaving now, so hopefully I''ll be there by six.","vi":"Tôi đi bây giờ đây, nên mong là sẽ tới đó trước sáu giờ."},{"en":"We''ve fixed the problem, and hopefully it won''t happen again.","vi":"Chúng tôi đã khắc phục sự cố, và hy vọng là nó sẽ không xảy ra nữa."}]', '[{"phrase":"hopefully not"},{"phrase":"hopefully soon"}]', NULL, '/ˈhəʊpfəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hop/hopef/hopefully__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-04', 29, 'sanction', 'lệnh trừng phạt; sự cho phép', 'noun', '[{"en":"Several countries have placed economic sanctions on the government.","vi":"Một số quốc gia đã áp đặt các lệnh trừng phạt kinh tế lên chính phủ này."},{"en":"The sanctions will be lifted if both sides reach an agreement.","vi":"Các lệnh trừng phạt sẽ được dỡ bỏ nếu hai bên đạt được thỏa thuận."},{"en":"Nobody may use the hall without the official sanction of the school.","vi":"Không ai được sử dụng hội trường khi chưa có sự cho phép chính thức của nhà trường."}]', '[{"phrase":"impose sanctions"},{"phrase":"economic sanctions"},{"phrase":"lift sanctions"},{"phrase":"trade sanctions"}]', 'Nghĩa "trừng phạt" thường dùng số nhiều: sanctions', '/ˈsæŋkʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/san/sanct/sanction__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-6-05', 'ngsl-6', 'Thông dụng 2.501–2.809 · Bộ 5', 'New General Service List, thứ hạng 2.501–2.809', '#3da9fc', 'BookOpen', 5);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 1, 'trick', 'trò lừa; mẹo; trò ảo thuật', 'noun', '[{"en":"Don''t believe him; it''s just a trick to get your money.","vi":"Đừng tin anh ta; đó chỉ là trò lừa để lấy tiền của bạn."},{"en":"Is there a trick to opening this jar?","vi":"Có mẹo nào để mở cái lọ này không?"},{"en":"My grandfather showed us a card trick after dinner.","vi":"Ông tôi cho chúng tôi xem một trò ảo thuật với bài sau bữa tối."}]', '[{"phrase":"play a trick on"},{"phrase":"magic trick"},{"phrase":"card trick"},{"phrase":"the trick is"}]', NULL, '/trɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tri/trick/trick__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 2, 'paragraph', 'đoạn văn', 'noun', '[{"en":"Please read the first paragraph out loud.","vi":"Hãy đọc to đoạn văn đầu tiên."},{"en":"Your essay should have at least five paragraphs.","vi":"Bài luận của bạn nên có ít nhất năm đoạn văn."},{"en":"I rewrote the last paragraph of my cover letter twice.","vi":"Tôi đã viết lại đoạn cuối của thư xin việc hai lần."}]', '[{"phrase":"first paragraph"},{"phrase":"opening paragraph"},{"phrase":"short paragraph"},{"phrase":"write a paragraph"}]', NULL, '/ˈpærəɡræf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/parag/paragraph__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 3, 'maker', 'hãng sản xuất; người làm ra; máy pha, máy làm', 'noun', '[{"en":"The phone maker plans to open a new factory next year.","vi":"Hãng sản xuất điện thoại dự định mở một nhà máy mới vào năm sau."},{"en":"My uncle is a furniture maker in a small village.","vi":"Chú tôi là thợ làm đồ gỗ ở một ngôi làng nhỏ."},{"en":"My sister bought a new coffee maker for her office.","vi":"Chị tôi đã mua một chiếc máy pha cà phê mới cho văn phòng."}]', '[{"phrase":"coffee maker"},{"phrase":"car maker"},{"phrase":"decision maker"},{"phrase":"furniture maker"}]', NULL, '/ˈmeɪkər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mak/maker/maker__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 4, 'chocolate', 'sô-cô-la', 'noun', '[{"en":"Would you like a cup of hot chocolate?","vi":"Bạn có muốn một cốc sô-cô-la nóng không?"},{"en":"She gave me a box of chocolates for my birthday.","vi":"Cô ấy tặng tôi một hộp sô-cô-la nhân dịp sinh nhật."},{"en":"The kids ate all the dark chocolate I bought.","vi":"Bọn trẻ đã ăn hết chỗ sô-cô-la đen tôi mua."}]', '[{"phrase":"hot chocolate"},{"phrase":"dark chocolate"},{"phrase":"box of chocolates"},{"phrase":"chocolate cake"}]', NULL, '/ˈtʃɔːklət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cho/choco/chocolate__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 5, 'stimulate', 'kích thích; thúc đẩy; khơi gợi', 'verb', '[{"en":"The government lowered taxes to stimulate the economy.","vi":"Chính phủ giảm thuế để kích thích nền kinh tế."},{"en":"Colorful pictures can stimulate children''s interest in reading.","vi":"Tranh ảnh nhiều màu sắc có thể khơi gợi hứng thú đọc sách của trẻ."},{"en":"Coffee stimulates the brain and helps you stay awake.","vi":"Cà phê kích thích não bộ và giúp bạn tỉnh táo."}]', '[{"phrase":"stimulate the economy"},{"phrase":"stimulate growth"},{"phrase":"stimulate interest"},{"phrase":"stimulate demand"}]', NULL, '/ˈstɪmjuleɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sti/stimu/stimulate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 6, 'belt', 'thắt lưng; dây đai; băng chuyền', 'noun', '[{"en":"These jeans are too big, so I need a belt.","vi":"Chiếc quần jean này rộng quá nên tôi cần một cái thắt lưng."},{"en":"Please fasten your seat belt before we start driving.","vi":"Hãy thắt dây an toàn trước khi chúng ta bắt đầu lái xe."},{"en":"Your bags will come out on that belt over there.","vi":"Hành lý của bạn sẽ ra trên băng chuyền đằng kia."}]', '[{"phrase":"seat belt"},{"phrase":"leather belt"},{"phrase":"conveyor belt"},{"phrase":"wear a belt"}]', 'seat belt: dây an toàn', '/belt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bel/belt_/belt__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 7, 'potato', 'khoai tây', 'noun', '[{"en":"Could you peel the potatoes while I cook the fish?","vi":"Bạn gọt khoai tây giúp tôi trong lúc tôi nấu cá được không?"},{"en":"We had baked potatoes with cheese for lunch.","vi":"Bữa trưa chúng tôi ăn khoai tây nướng với phô mai."},{"en":"My grandmother grows potatoes and onions in her garden.","vi":"Bà tôi trồng khoai tây và hành trong vườn."}]', '[{"phrase":"baked potato"},{"phrase":"mashed potatoes"},{"phrase":"sweet potato"},{"phrase":"peel potatoes"}]', 'số nhiều: potatoes', '/pəˈteɪtəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pot/potat/potato__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 8, 'narrative', 'câu chuyện; lời kể; bài văn tự sự', 'noun', '[{"en":"The narrative of the novel moves between the past and the present.","vi":"Câu chuyện trong cuốn tiểu thuyết đan xen giữa quá khứ và hiện tại."},{"en":"Her narrative of the trip was clear and full of detail.","vi":"Lời kể của cô ấy về chuyến đi rất rõ ràng và đầy chi tiết."},{"en":"Each student wrote a short personal narrative about their summer.","vi":"Mỗi học sinh viết một bài văn tự sự ngắn về mùa hè của mình."}]', '[{"phrase":"personal narrative"},{"phrase":"historical narrative"},{"phrase":"a clear narrative"}]', NULL, '/ˈnærətɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nar/narra/narrative__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 9, 'tissue', 'khăn giấy; mô (cơ thể)', 'noun', '[{"en":"She handed me a tissue when I started to cry.","vi":"Cô ấy đưa tôi một tờ khăn giấy khi tôi bắt đầu khóc."},{"en":"Please put a box of tissues on each table.","vi":"Vui lòng đặt một hộp khăn giấy trên mỗi bàn."},{"en":"Regular exercise helps your body build strong muscle tissue.","vi":"Tập thể dục đều đặn giúp cơ thể xây dựng mô cơ khỏe mạnh."}]', '[{"phrase":"box of tissues"},{"phrase":"muscle tissue"},{"phrase":"soft tissue"}]', NULL, '/ˈtɪʃuː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tis/tissu/tissue__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 10, 'barely', 'hầu như không; vừa đủ', 'adverb', '[{"en":"I could barely hear her over the loud music.","vi":"Tôi gần như không nghe thấy cô ấy nói vì tiếng nhạc quá to."},{"en":"We barely had enough time to catch the train.","vi":"Chúng tôi chỉ vừa đủ thời gian để kịp chuyến tàu."},{"en":"He was so tired that he barely spoke at dinner.","vi":"Anh ấy mệt đến mức hầu như không nói gì trong bữa tối."}]', '[{"phrase":"barely enough"},{"phrase":"can barely"},{"phrase":"barely notice"}]', NULL, '/ˈberli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bar/barel/barely__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 11, 'invent', 'phát minh; nghĩ ra; bịa ra', 'verb', '[{"en":"Nobody knows exactly who invented the first bicycle.","vi":"Không ai biết chính xác ai đã phát minh ra chiếc xe đạp đầu tiên."},{"en":"My son loves to invent new games with his friends.","vi":"Con trai tôi thích nghĩ ra trò chơi mới cùng bạn bè."},{"en":"He invented an excuse for being late to work.","vi":"Anh ấy bịa ra một lý do cho việc đi làm muộn."}]', '[{"phrase":"invent an excuse"},{"phrase":"invent a story"},{"phrase":"invent a new way"}]', NULL, '/ɪnˈvent/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/inven/invent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 12, 'tourism', 'du lịch; ngành du lịch', 'noun', '[{"en":"The tourism industry creates thousands of jobs on the island.","vi":"Ngành du lịch tạo ra hàng nghìn việc làm trên hòn đảo."},{"en":"The new airport has helped tourism grow in the region.","vi":"Sân bay mới đã giúp du lịch trong vùng phát triển."},{"en":"She works in tourism and speaks four languages.","vi":"Cô ấy làm trong ngành du lịch và nói được bốn thứ tiếng."}]', '[{"phrase":"tourism industry"},{"phrase":"boost tourism"},{"phrase":"mass tourism"}]', 'không đếm được', '/ˈtʊrɪzəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tou/touri/tourism__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 13, 'pro', 'dân chuyên nghiệp; người thành thạo; ưu điểm', 'noun', '[{"en":"My brother wants to turn pro after finishing college.","vi":"Anh trai tôi muốn trở thành vận động viên chuyên nghiệp sau khi học xong đại học."},{"en":"After ten years of cooking, he''s a real pro in the kitchen.","vi":"Sau mười năm nấu nướng, anh ấy là một tay lão luyện thực thụ trong bếp."},{"en":"Let''s write down the pros and cons before we decide.","vi":"Hãy viết ra những ưu và nhược điểm trước khi chúng ta quyết định."}]', '[{"phrase":"pros and cons"},{"phrase":"turn pro"},{"phrase":"like a pro"},{"phrase":"a real pro"}]', 'viết tắt của professional; pros and cons: ưu và nhược điểm', '/prəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/pro__/pro__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 14, 'stair', 'bậc thang; cầu thang', 'noun', '[{"en":"He sat on the bottom stair to tie his shoes.","vi":"Anh ấy ngồi ở bậc thang dưới cùng để buộc dây giày."},{"en":"Take the stairs if the elevator is too slow.","vi":"Hãy đi cầu thang bộ nếu thang máy quá chậm."},{"en":"I heard someone running up the stairs.","vi":"Tôi nghe thấy ai đó chạy lên cầu thang."}]', '[{"phrase":"take the stairs"},{"phrase":"climb the stairs"},{"phrase":"flight of stairs"},{"phrase":"bottom stair"}]', 'thường dùng số nhiều: stairs (cầu thang)', '/ster/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stair/stair__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 15, 'hesitate', 'do dự; ngần ngại', 'verb', '[{"en":"Don''t hesitate to call me if you need help.","vi":"Đừng ngần ngại gọi cho tôi nếu bạn cần giúp đỡ."},{"en":"She hesitated for a moment before opening the door.","vi":"Cô ấy do dự một lúc trước khi mở cửa."},{"en":"When they offered him the job, he didn''t hesitate.","vi":"Khi họ mời anh ấy nhận việc, anh ấy không hề do dự."}]', '[{"phrase":"don''t hesitate to"},{"phrase":"hesitate for a moment"},{"phrase":"hesitate before"}]', NULL, '/ˈhezɪteɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hes/hesit/hesitate__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 16, 'shine', 'chiếu sáng; tỏa sáng; sáng lên', 'verb', '[{"en":"The sun was shining when we arrived at the beach.","vi":"Mặt trời đang chiếu sáng rực rỡ khi chúng tôi đến bãi biển."},{"en":"Her eyes shone with excitement when she opened the gift.","vi":"Mắt cô ấy sáng lên vì háo hức khi mở món quà."},{"en":"He really shines when he talks about music.","vi":"Anh ấy thực sự tỏa sáng khi nói về âm nhạc."}]', '[{"phrase":"the sun shines"},{"phrase":"shine brightly"},{"phrase":"shine a light"},{"phrase":"eyes shine"}]', 'shine – shone – shone', '/ʃaɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/shi/shine/shine__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 17, 'motivation', 'động lực; sự thúc đẩy', 'noun', '[{"en":"I lost my motivation to study after failing the test.","vi":"Tôi mất động lực học sau khi thi trượt."},{"en":"Money isn''t his only motivation for working so hard.","vi":"Tiền không phải là động lực duy nhất khiến anh ấy làm việc chăm chỉ như vậy."},{"en":"Good managers know how to keep their team''s motivation high.","vi":"Người quản lý giỏi biết cách giữ cho đội ngũ luôn có động lực cao."}]', '[{"phrase":"motivation to"},{"phrase":"lack of motivation"},{"phrase":"lose motivation"},{"phrase":"high motivation"}]', NULL, '/ˌməʊtɪˈveɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mot/motiv/motivation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 18, 'romantic', 'lãng mạn', 'adjective', '[{"en":"We had a romantic dinner by the river.","vi":"Chúng tôi đã có một bữa tối lãng mạn bên bờ sông."},{"en":"My husband isn''t very romantic, but he''s very kind.","vi":"Chồng tôi không lãng mạn lắm, nhưng anh ấy rất tốt bụng."},{"en":"She loves watching romantic comedies on Friday nights.","vi":"Cô ấy thích xem phim hài lãng mạn vào các tối thứ Sáu."}]', '[{"phrase":"romantic dinner"},{"phrase":"romantic comedy"},{"phrase":"romantic relationship"},{"phrase":"romantic evening"}]', NULL, '/rəʊˈmæntɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rom/roman/romantic__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 19, 'firmly', 'chặt; kiên quyết; vững chắc', 'adverb', '[{"en":"Hold the ladder firmly while I climb up.","vi":"Hãy giữ chặt cái thang trong khi tôi trèo lên."},{"en":"She said no firmly and walked away.","vi":"Cô ấy kiên quyết nói không rồi bỏ đi."},{"en":"I firmly believe that everyone deserves a second chance.","vi":"Tôi tin chắc rằng ai cũng xứng đáng có cơ hội thứ hai."}]', '[{"phrase":"firmly believe"},{"phrase":"hold firmly"},{"phrase":"firmly established"}]', NULL, '/ˈfɜːrmli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fir/firml/firmly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 20, 'interior', 'nội thất; phần bên trong', 'noun', '[{"en":"The interior of the house is much bigger than it looks.","vi":"Bên trong ngôi nhà rộng hơn nhiều so với vẻ bề ngoài."},{"en":"The car''s interior smells like new leather.","vi":"Nội thất của chiếc xe có mùi da mới."},{"en":"My cousin studied interior design and now decorates hotels.","vi":"Em họ tôi học thiết kế nội thất và giờ đi trang trí khách sạn."}]', '[{"phrase":"interior design"},{"phrase":"the interior of"},{"phrase":"car interior"}]', NULL, '/ɪnˈtɪriər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/interior__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 21, 'stomach', 'dạ dày; bụng', 'noun', '[{"en":"I''ve had a stomach ache since this morning.","vi":"Tôi bị đau bụng từ sáng nay."},{"en":"Try not to go swimming on a full stomach.","vi":"Cố đừng đi bơi khi vừa ăn no."},{"en":"He lay on his stomach and read a book.","vi":"Anh ấy nằm sấp và đọc sách."}]', '[{"phrase":"stomach ache"},{"phrase":"empty stomach"},{"phrase":"full stomach"},{"phrase":"upset stomach"}]', 'on an empty stomach: lúc bụng đói', '/ˈstʌmək/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sto/stoma/stomach__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 22, 'nowhere', 'không nơi nào; không đâu', 'adverb', '[{"en":"There''s nowhere to park near the stadium.","vi":"Gần sân vận động không có chỗ nào để đỗ xe."},{"en":"We looked everywhere, but the cat was nowhere to be found.","vi":"Chúng tôi tìm khắp nơi nhưng không thấy con mèo ở đâu cả."},{"en":"Arguing with your boss will get you nowhere.","vi":"Cãi nhau với sếp sẽ chẳng đưa bạn đến đâu cả."}]', '[{"phrase":"nowhere to go"},{"phrase":"nowhere to be found"},{"phrase":"get nowhere"},{"phrase":"in the middle of nowhere"}]', NULL, '/ˈnəʊwer/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/now/nowhe/nowhere__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 23, 'pray', 'cầu nguyện; cầu mong', 'verb', '[{"en":"We''re all praying for good weather on the wedding day.","vi":"Tất cả chúng tôi đều cầu mong trời đẹp vào ngày cưới."},{"en":"She prayed that her son would get home safely.","vi":"Cô ấy cầu mong con trai về nhà an toàn."},{"en":"My grandmother prays every morning before breakfast.","vi":"Bà tôi cầu nguyện mỗi sáng trước khi ăn sáng."}]', '[{"phrase":"pray for"},{"phrase":"pray that"}]', NULL, '/preɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pra/pray_/pray__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 24, 'championship', 'giải vô địch; chức vô địch', 'noun', '[{"en":"Our school team won the basketball championship this year.","vi":"Đội của trường chúng tôi đã vô địch giải bóng rổ năm nay."},{"en":"She''s training hard for the world championships next month.","vi":"Cô ấy đang tập luyện chăm chỉ cho giải vô địch thế giới vào tháng tới."},{"en":"The last game of the season will decide the championship.","vi":"Trận đấu cuối cùng của mùa giải sẽ quyết định chức vô địch."}]', '[{"phrase":"win the championship"},{"phrase":"world championship"},{"phrase":"national championship"}]', NULL, '/ˈtʃæmpiənʃɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/champ/championship__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 25, 'servant', 'người hầu; người phục vụ', 'noun', '[{"en":"In the story, a loyal servant saves the young prince.","vi":"Trong câu chuyện, một người hầu trung thành đã cứu hoàng tử trẻ."},{"en":"The old house had small rooms upstairs for the servants.","vi":"Ngôi nhà cổ có những phòng nhỏ trên lầu dành cho người hầu."},{"en":"The rich family had three servants to cook and clean.","vi":"Gia đình giàu có đó có ba người hầu để nấu nướng và dọn dẹp."}]', '[{"phrase":"loyal servant"},{"phrase":"civil servant"},{"phrase":"public servant"}]', 'civil servant: công chức', '/ˈsɜːrvənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ser/serva/servant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 26, 'immigrant', 'người nhập cư', 'noun', '[{"en":"Many immigrants came to the city looking for work.","vi":"Nhiều người nhập cư đã đến thành phố để tìm việc làm."},{"en":"My grandparents were immigrants who opened a small bakery.","vi":"Ông bà tôi là người nhập cư và đã mở một tiệm bánh nhỏ."},{"en":"The school offers free English classes for new immigrants.","vi":"Trường có các lớp tiếng Anh miễn phí dành cho người mới nhập cư."}]', '[{"phrase":"new immigrants"},{"phrase":"immigrant family"},{"phrase":"immigrant workers"}]', 'immigrant (người nhập cư) ≠ emigrant (người di cư ra nước ngoài)', '/ˈɪmɪɡrənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imm/immig/immigrant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 27, 'excess', 'sự dư thừa; phần thừa; sự vượt quá', 'noun', '[{"en":"Eating sugar in excess is bad for your teeth.","vi":"Ăn quá nhiều đường không tốt cho răng."},{"en":"After gluing the edges, wipe off the excess with a cloth.","vi":"Sau khi dán các mép, hãy dùng khăn lau sạch phần keo thừa."},{"en":"This bridge can''t carry loads in excess of ten tons.","vi":"Cây cầu này không chịu được tải trọng vượt quá mười tấn."}]', '[{"phrase":"in excess"},{"phrase":"in excess of"},{"phrase":"an excess of"},{"phrase":"excess baggage"}]', NULL, '/ɪkˈses/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/exces/excess__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 28, 'complexity', 'sự phức tạp; tính phức tạp', 'noun', '[{"en":"Few people understand the complexity of the tax system.","vi":"Ít người hiểu được sự phức tạp của hệ thống thuế."},{"en":"The project grew in complexity as more people joined.","vi":"Dự án ngày càng phức tạp khi có thêm nhiều người tham gia."},{"en":"Many parents are surprised by the complexity of raising a teenager.","vi":"Nhiều bậc cha mẹ bất ngờ trước sự phức tạp của việc nuôi dạy con tuổi mới lớn."}]', '[{"phrase":"the complexity of"},{"phrase":"grow in complexity"},{"phrase":"increasing complexity"},{"phrase":"great complexity"}]', NULL, '/kəmˈpleksəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compl/complexity__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-05', 29, 'liability', 'trách nhiệm pháp lý; khoản nợ; gánh nặng', 'noun', '[{"en":"The company accepted liability for the damage to our car.","vi":"Công ty đã nhận trách nhiệm pháp lý về thiệt hại cho xe của chúng tôi."},{"en":"The small shop closed because its liabilities grew too large.","vi":"Cửa hàng nhỏ phải đóng cửa vì các khoản nợ trở nên quá lớn."},{"en":"His bad temper has become a liability for the team.","vi":"Tính nóng nảy của anh ấy đã trở thành gánh nặng cho cả đội."}]', '[{"phrase":"accept liability"},{"phrase":"legal liability"},{"phrase":"limited liability"},{"phrase":"deny liability"}]', NULL, '/ˌlaɪəˈbɪləti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lia/liabi/liability__us_2.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-6-06', 'ngsl-6', 'Thông dụng 2.501–2.809 · Bộ 6', 'New General Service List, thứ hạng 2.501–2.809', '#3da9fc', 'BookOpen', 6);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 1, 'surprisingly', 'một cách đáng ngạc nhiên; bất ngờ thay', 'adverb', '[{"en":"The test was surprisingly easy, so everyone finished early.","vi":"Bài kiểm tra dễ một cách đáng ngạc nhiên, nên ai cũng làm xong sớm."},{"en":"Not surprisingly, the kids were tired after the long trip.","vi":"Chẳng có gì ngạc nhiên khi bọn trẻ mệt sau chuyến đi dài."},{"en":"Surprisingly, nobody in the office noticed that the lights were off.","vi":"Bất ngờ thay, không ai trong văn phòng để ý rằng đèn đã tắt."}]', '[{"phrase":"not surprisingly"},{"phrase":"surprisingly good"},{"phrase":"surprisingly easy"},{"phrase":"surprisingly few"}]', NULL, '/sərˈpraɪzɪŋli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/surpr/surprisingly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 2, 'extract', 'chiết xuất; lấy ra; nhổ (răng)', 'verb', '[{"en":"The oil is extracted from the seeds of the plant.","vi":"Dầu được chiết xuất từ hạt của loại cây này."},{"en":"The app can extract text from a photo in seconds.","vi":"Ứng dụng có thể lấy chữ ra từ một bức ảnh chỉ trong vài giây."},{"en":"The dentist had to extract two of my teeth last month.","vi":"Tháng trước nha sĩ phải nhổ hai cái răng của tôi."}]', '[{"phrase":"extract information"},{"phrase":"extract data"},{"phrase":"extract oil"},{"phrase":"extract a tooth"}]', 'extract sth from sth', '/ˈekstrækt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/extra/extract__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 3, 'implementation', 'sự thực hiện; sự triển khai', 'noun', '[{"en":"The implementation of the new rules will begin next month.","vi":"Việc thực hiện các quy định mới sẽ bắt đầu vào tháng sau."},{"en":"We need more staff for the implementation of this project.","vi":"Chúng tôi cần thêm nhân viên để triển khai dự án này."},{"en":"Good ideas often fail because of poor implementation.","vi":"Ý tưởng hay thường thất bại vì triển khai kém."}]', '[{"phrase":"implementation of"},{"phrase":"full implementation"},{"phrase":"successful implementation"},{"phrase":"policy implementation"}]', NULL, '/ˌɪmplɪmenˈteɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/imple/implementation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 4, 'bias', 'sự thiên vị; thành kiến', 'noun', '[{"en":"The teacher tried hard to grade every student without bias.","vi":"Giáo viên đã cố gắng chấm điểm mọi học sinh mà không thiên vị."},{"en":"Many people have a bias against workers who are older.","vi":"Nhiều người có thành kiến với những người lao động lớn tuổi hơn."},{"en":"Does this news report show a clear bias?","vi":"Bản tin này có thể hiện sự thiên vị rõ ràng không?"}]', '[{"phrase":"bias against"},{"phrase":"bias toward"},{"phrase":"political bias"},{"phrase":"without bias"}]', NULL, '/ˈbaɪəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bia/bias_/bias__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 5, 'differently', 'khác; theo cách khác', 'adverb', '[{"en":"My brother and I see things very differently.","vi":"Anh trai tôi và tôi nhìn nhận mọi việc rất khác nhau."},{"en":"If I could start again, I would do it differently.","vi":"Nếu được bắt đầu lại, tôi sẽ làm theo cách khác."},{"en":"Children often behave differently when their parents are not around.","vi":"Trẻ con thường cư xử khác đi khi bố mẹ không ở bên cạnh."}]', '[{"phrase":"think differently"},{"phrase":"do things differently"},{"phrase":"treat differently"},{"phrase":"see things differently"}]', NULL, '/ˈdɪfrəntli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dif/diffe/differently__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 6, 'catalog', 'danh mục; catalô (sách giới thiệu sản phẩm)', 'noun', '[{"en":"I found this lamp in an online catalog last week.","vi":"Tôi tìm thấy cái đèn này trong một danh mục trực tuyến tuần trước."},{"en":"The store sends us a new catalog every spring.","vi":"Cửa hàng gửi cho chúng tôi một cuốn catalô mới vào mỗi mùa xuân."},{"en":"You can search the library catalog to see if the book is available.","vi":"Bạn có thể tra danh mục thư viện để xem cuốn sách có sẵn không."}]', '[{"phrase":"online catalog"},{"phrase":"library catalog"},{"phrase":"product catalog"},{"phrase":"mail-order catalog"}]', 'Mỹ: catalog · Anh: catalogue', '/ˈkætəlɔɡ/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 7, 'continuous', 'liên tục; không ngừng', 'adjective', '[{"en":"The baby needs continuous care during the first few weeks.","vi":"Em bé cần được chăm sóc liên tục trong vài tuần đầu."},{"en":"We had three days of continuous rain last week.","vi":"Tuần trước trời mưa liên tục ba ngày."},{"en":"The factory runs a continuous process, day and night.","vi":"Nhà máy vận hành một quy trình liên tục, cả ngày lẫn đêm."}]', '[{"phrase":"continuous process"},{"phrase":"continuous improvement"},{"phrase":"continuous flow"},{"phrase":"continuous use"}]', 'continuous (liên tục không gián đoạn) ≠ continual (lặp đi lặp lại)', '/kənˈtɪnjuəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontinuous__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 8, 'golden', '(màu) vàng óng; bằng vàng; quý giá', 'adjective', '[{"en":"Bake the bread until the top is golden brown.","vi":"Nướng bánh mì cho đến khi mặt trên có màu vàng nâu."},{"en":"She wore a small golden ring on her left hand.","vi":"Cô ấy đeo một chiếc nhẫn vàng nhỏ ở tay trái."},{"en":"This job offer is a golden opportunity, so don''t miss it.","vi":"Lời mời làm việc này là một cơ hội vàng, đừng bỏ lỡ nhé."}]', '[{"phrase":"golden brown"},{"phrase":"golden opportunity"},{"phrase":"golden hair"},{"phrase":"golden rule"}]', NULL, '/ˈɡəʊldən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gol/golde/golden__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 9, 'stamp', 'tem (thư); con dấu', 'noun', '[{"en":"Don''t forget to put a stamp on the letter.","vi":"Đừng quên dán tem lên lá thư nhé."},{"en":"My grandfather has collected stamps from many countries.","vi":"Ông tôi đã sưu tầm tem của nhiều nước."},{"en":"The officer put a stamp in my passport at the airport.","vi":"Nhân viên đóng dấu vào hộ chiếu của tôi ở sân bay."}]', '[{"phrase":"postage stamp"},{"phrase":"stamp collection"},{"phrase":"put a stamp on"},{"phrase":"rubber stamp"}]', NULL, '/stæmp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stamp/stamp__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 10, 'guideline', 'hướng dẫn; nguyên tắc chỉ đạo', 'noun', '[{"en":"Please read the safety guidelines before using the machine.","vi":"Vui lòng đọc hướng dẫn an toàn trước khi sử dụng máy."},{"en":"The school has published new guidelines for online classes.","vi":"Nhà trường đã ban hành hướng dẫn mới cho các lớp học trực tuyến."},{"en":"All staff must follow these guidelines when talking to customers.","vi":"Mọi nhân viên phải tuân theo các nguyên tắc này khi nói chuyện với khách hàng."}]', '[{"phrase":"follow guidelines"},{"phrase":"safety guidelines"},{"phrase":"clear guidelines"},{"phrase":"issue guidelines"}]', 'Thường dùng ở số nhiều: guidelines', '/ˈɡaɪdlaɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gui/guide/guideline__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 11, 'envelope', 'phong bì', 'noun', '[{"en":"She put the card in an envelope and sealed it.","vi":"Cô ấy bỏ tấm thiếp vào phong bì rồi dán lại."},{"en":"Write your address clearly on the front of the envelope.","vi":"Hãy viết rõ địa chỉ của bạn ở mặt trước phong bì."},{"en":"My grandmother gave each of us an envelope with some money inside.","vi":"Bà tôi cho mỗi đứa chúng tôi một phong bì có ít tiền bên trong."}]', '[{"phrase":"open an envelope"},{"phrase":"seal an envelope"},{"phrase":"brown envelope"},{"phrase":"stamped envelope"}]', NULL, '/ˈenvələʊp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/env/envel/envelope__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 12, 'knife', 'con dao', 'noun', '[{"en":"Be careful, that knife is very sharp.","vi":"Cẩn thận nhé, con dao đó rất sắc."},{"en":"He cut the cake into eight pieces with a large knife.","vi":"Anh ấy dùng một con dao lớn cắt bánh thành tám miếng."},{"en":"Could you pass me a knife and fork, please?","vi":"Bạn đưa giúp tôi một bộ dao nĩa được không?"}]', '[{"phrase":"sharp knife"},{"phrase":"kitchen knife"},{"phrase":"knife and fork"},{"phrase":"bread knife"}]', 'Số nhiều: knives', '/naɪf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kni/knife/knife__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 13, 'biological', '(thuộc) sinh học; ruột thịt (cha mẹ)', 'adjective', '[{"en":"Sleep is a basic biological need for all humans.","vi":"Ngủ là một nhu cầu sinh học cơ bản của mọi người."},{"en":"The scientists are studying the biological effects of the new drug.","vi":"Các nhà khoa học đang nghiên cứu tác động sinh học của loại thuốc mới."},{"en":"He was adopted and never met his biological parents.","vi":"Anh ấy là con nuôi và chưa bao giờ gặp cha mẹ ruột của mình."}]', '[{"phrase":"biological parents"},{"phrase":"biological process"},{"phrase":"biological clock"},{"phrase":"biological need"}]', NULL, '/ˌbaɪəˈlɑːdʒɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bio/biolo/biological__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 14, 'consume', 'tiêu thụ; tiêu tốn; ăn, uống', 'verb', '[{"en":"Old fridges consume a lot more electricity than new ones.","vi":"Tủ lạnh cũ tiêu thụ nhiều điện hơn hẳn tủ lạnh mới."},{"en":"This task consumed most of my time last week.","vi":"Công việc này đã tiêu tốn phần lớn thời gian của tôi tuần trước."},{"en":"Most people consume too much sugar without realizing it.","vi":"Hầu hết mọi người ăn quá nhiều đường mà không nhận ra."}]', '[{"phrase":"consume energy"},{"phrase":"consume food"},{"phrase":"consume alcohol"},{"phrase":"consume calories"}]', NULL, '/kənˈsuːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsume__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 15, 'luxury', 'sự xa xỉ; đồ xa xỉ; sang trọng', 'noun', '[{"en":"They stayed in a luxury hotel for their honeymoon.","vi":"Họ ở một khách sạn sang trọng trong tuần trăng mật."},{"en":"For many students, eating out is a luxury.","vi":"Với nhiều sinh viên, ăn ngoài là một thứ xa xỉ."},{"en":"After the war, they could not afford any luxuries.","vi":"Sau chiến tranh, họ không thể mua nổi bất kỳ món đồ xa xỉ nào."}]', '[{"phrase":"luxury hotel"},{"phrase":"luxury goods"},{"phrase":"a life of luxury"},{"phrase":"afford the luxury of"}]', NULL, '/ˈlʌkʃəri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lux/luxur/luxury__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 16, 'weekly', 'hằng tuần', 'adjective', '[{"en":"Our team has a weekly meeting every Monday morning.","vi":"Nhóm chúng tôi có buổi họp hằng tuần vào mỗi sáng thứ Hai."},{"en":"I do the weekly shopping at the market on Saturdays.","vi":"Tôi đi chợ mua đồ cho cả tuần vào các ngày thứ Bảy."},{"en":"The magazine is published weekly and costs three dollars.","vi":"Tạp chí này ra hằng tuần và có giá ba đô la."}]', '[{"phrase":"weekly meeting"},{"phrase":"weekly basis"},{"phrase":"weekly shopping"},{"phrase":"twice weekly"}]', NULL, '/ˈwiːkli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wee/weekl/weekly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 17, 'wherever', 'bất cứ nơi đâu; ở đâu cũng', 'conjunction', '[{"en":"You can sit wherever you like in the classroom.","vi":"Em có thể ngồi bất cứ chỗ nào em thích trong lớp."},{"en":"My dog follows me wherever I go.","vi":"Con chó của tôi theo tôi đi bất cứ nơi đâu."},{"en":"Wherever you are in the city, you can see the tower.","vi":"Dù bạn ở đâu trong thành phố, bạn cũng có thể nhìn thấy ngọn tháp."}]', '[{"phrase":"wherever you go"},{"phrase":"wherever possible"},{"phrase":"wherever you like"},{"phrase":"wherever you are"}]', NULL, '/werˈevər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whe/where/wherever__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 18, 'bite', 'cắn; (côn trùng) đốt', 'verb', '[{"en":"Don''t worry, our dog has never bitten anyone.","vi":"Đừng lo, con chó nhà tôi chưa bao giờ cắn ai cả."},{"en":"I got bitten by mosquitoes all night at the campsite.","vi":"Tôi bị muỗi đốt suốt đêm ở khu cắm trại."},{"en":"Try not to bite your nails when you feel nervous.","vi":"Cố gắng đừng cắn móng tay khi bạn thấy lo lắng."}]', '[{"phrase":"bite your nails"},{"phrase":"bite into"},{"phrase":"bite your lip"},{"phrase":"get bitten"}]', 'bite – bit – bitten', '/baɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bit/bite_/bite__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 19, 'printer', 'máy in', 'noun', '[{"en":"The printer in our office has run out of paper again.","vi":"Máy in ở văn phòng chúng tôi lại hết giấy rồi."},{"en":"Can I use your printer to print my plane ticket?","vi":"Tôi dùng máy in của bạn để in vé máy bay được không?"},{"en":"We bought a cheap printer, but the ink is really expensive.","vi":"Chúng tôi mua một cái máy in rẻ, nhưng mực thì đắt thật."}]', '[{"phrase":"laser printer"},{"phrase":"printer ink"},{"phrase":"color printer"},{"phrase":"printer paper"}]', NULL, '/ˈprɪntər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/print/printer__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 20, 'firstly', 'thứ nhất; trước hết', 'adverb', '[{"en":"Firstly, I would like to thank everyone for coming today.","vi":"Trước hết, tôi xin cảm ơn mọi người đã đến hôm nay."},{"en":"I can''t go, firstly because I''m busy and secondly because it''s expensive.","vi":"Tôi không đi được, thứ nhất vì tôi bận và thứ hai vì nó đắt."},{"en":"Firstly, turn off the power before you clean the machine.","vi":"Trước hết, hãy tắt nguồn trước khi lau chùi máy."}]', '[{"phrase":"firstly, secondly"},{"phrase":"firstly because"}]', 'Dùng để liệt kê ý: firstly, secondly, finally', '/ˈfɜːrstli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fir/first/firstly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 21, 'anxious', 'lo lắng; nóng lòng, mong muốn', 'adjective', '[{"en":"She always feels anxious before a big exam.","vi":"Cô ấy luôn cảm thấy lo lắng trước một kỳ thi quan trọng."},{"en":"My parents were anxious about my long trip alone.","vi":"Bố mẹ tôi lo lắng về chuyến đi dài một mình của tôi."},{"en":"We are anxious to hear your answer as soon as possible.","vi":"Chúng tôi nóng lòng muốn nghe câu trả lời của bạn càng sớm càng tốt."}]', '[{"phrase":"anxious about"},{"phrase":"feel anxious"},{"phrase":"anxious to do"},{"phrase":"increasingly anxious"}]', 'anxious about sth · anxious to do sth', '/ˈæŋkʃəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/anx/anxio/anxious__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 22, 'adventure', 'cuộc phiêu lưu; sự mạo hiểm', 'noun', '[{"en":"Our trip through the mountains was a real adventure.","vi":"Chuyến đi xuyên qua núi của chúng tôi là một cuộc phiêu lưu thực sự."},{"en":"The children love reading adventure stories before bed.","vi":"Bọn trẻ thích đọc truyện phiêu lưu trước khi đi ngủ."},{"en":"He quit his job because he wanted more adventure in his life.","vi":"Anh ấy bỏ việc vì muốn cuộc sống có thêm nhiều trải nghiệm mạo hiểm."}]', '[{"phrase":"a real adventure"},{"phrase":"adventure story"},{"phrase":"sense of adventure"},{"phrase":"adventure travel"}]', NULL, '/ədˈventʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/adven/adventure__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 23, 'fence', 'hàng rào', 'noun', '[{"en":"We built a wooden fence around the garden.","vi":"Chúng tôi dựng một hàng rào gỗ quanh khu vườn."},{"en":"The cat jumped over the fence and ran away.","vi":"Con mèo nhảy qua hàng rào rồi chạy mất."},{"en":"There is a tall fence between our house and the road.","vi":"Có một hàng rào cao giữa nhà chúng tôi và con đường."}]', '[{"phrase":"wooden fence"},{"phrase":"build a fence"},{"phrase":"over the fence"},{"phrase":"electric fence"}]', NULL, '/fens/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fen/fence/fence__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 24, 'exhaust', 'làm kiệt sức; dùng cạn; khí thải', 'verb', '[{"en":"The long walk in the heat completely exhausted me.","vi":"Chuyến đi bộ dài dưới trời nóng khiến tôi hoàn toàn kiệt sức."},{"en":"We have exhausted all our options, so we need a new plan.","vi":"Chúng ta đã dùng hết mọi phương án, nên cần một kế hoạch mới."},{"en":"The city is trying to reduce exhaust from cars and buses.","vi":"Thành phố đang cố gắng giảm khí thải từ ô tô và xe buýt."}]', '[{"phrase":"exhaust fumes"},{"phrase":"exhaust pipe"},{"phrase":"exhaust all options"},{"phrase":"exhaust resources"}]', 'Tính từ: exhausted (kiệt sức), exhausting (gây mệt mỏi)', '/ɪɡˈzɔːst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exh/exhau/exhaust__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 25, 'attraction', 'điểm tham quan; sự thu hút; sức hấp dẫn', 'noun', '[{"en":"The old bridge is the main tourist attraction in our town.","vi":"Cây cầu cổ là điểm tham quan chính của thị trấn chúng tôi."},{"en":"The beach is the biggest attraction of this hotel.","vi":"Bãi biển là điểm thu hút lớn nhất của khách sạn này."},{"en":"I don''t understand the attraction of watching TV all day.","vi":"Tôi không hiểu việc xem TV cả ngày có gì hấp dẫn."}]', '[{"phrase":"tourist attraction"},{"phrase":"main attraction"},{"phrase":"major attraction"},{"phrase":"attraction of"}]', NULL, '/əˈtrækʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attra/attraction__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 26, 'ocean', 'đại dương; biển', 'noun', '[{"en":"We rented a small house with a view of the ocean.","vi":"Chúng tôi thuê một căn nhà nhỏ nhìn ra biển."},{"en":"Plastic waste is a serious problem for the world''s oceans.","vi":"Rác thải nhựa là một vấn đề nghiêm trọng đối với các đại dương trên thế giới."},{"en":"Have you ever swum in the ocean at night?","vi":"Bạn đã bao giờ bơi ở biển vào ban đêm chưa?"}]', '[{"phrase":"Pacific Ocean"},{"phrase":"ocean floor"},{"phrase":"across the ocean"},{"phrase":"ocean view"}]', NULL, '/ˈəʊʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/oce/ocean/ocean__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 27, 'quietly', 'một cách lặng lẽ; khẽ, nhỏ nhẹ', 'adverb', '[{"en":"Please talk quietly because the baby is asleep.","vi":"Làm ơn nói nhỏ thôi vì em bé đang ngủ."},{"en":"He quietly closed the door and left the room.","vi":"Anh ấy lặng lẽ đóng cửa và rời khỏi phòng."},{"en":"The students sat quietly and waited for the test to begin.","vi":"Học sinh ngồi yên lặng và chờ bài kiểm tra bắt đầu."}]', '[{"phrase":"speak quietly"},{"phrase":"sit quietly"},{"phrase":"work quietly"},{"phrase":"quietly confident"}]', NULL, '/ˈkwaɪətli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qui/quiet/quietly__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 28, 'castle', 'lâu đài', 'noun', '[{"en":"We visited an old castle on a hill near the river.","vi":"Chúng tôi đã tham quan một lâu đài cổ trên đồi gần con sông."},{"en":"The kids spent the afternoon building sand castles on the beach.","vi":"Bọn trẻ dành cả buổi chiều xây lâu đài cát trên bãi biển."},{"en":"This castle was built more than seven hundred years ago.","vi":"Lâu đài này được xây dựng cách đây hơn bảy trăm năm."}]', '[{"phrase":"old castle"},{"phrase":"sand castle"},{"phrase":"castle walls"},{"phrase":"medieval castle"}]', NULL, '/ˈkæsl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cas/castl/castle__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-06', 29, 'veteran', 'cựu chiến binh; người kỳ cựu, lão luyện', 'noun', '[{"en":"My grandfather is a veteran and often talks about his army days.","vi":"Ông tôi là cựu chiến binh và thường kể về những ngày trong quân đội."},{"en":"The town held a special lunch for local veterans.","vi":"Thị trấn tổ chức một bữa trưa đặc biệt dành cho các cựu chiến binh địa phương."},{"en":"She is a veteran of the hotel business with thirty years of experience.","vi":"Bà ấy là người kỳ cựu trong ngành khách sạn với ba mươi năm kinh nghiệm."}]', '[{"phrase":"war veteran"},{"phrase":"army veteran"},{"phrase":"veteran of"},{"phrase":"veteran player"}]', NULL, '/ˈvetərən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vet/veter/veteran__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-6-11', 'ngsl-6', 'Thông dụng 2.501–2.809 · Bộ 11', 'New General Service List, thứ hạng 2.501–2.809', '#3da9fc', 'BookOpen', 11);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-11', 1, 'faithfully', 'trung thành; tận tụy; sát, chính xác', 'adverb', '[{"en":"Our dog waited faithfully by the door until we came home.","vi":"Chú chó của chúng tôi trung thành chờ bên cửa cho đến khi chúng tôi về nhà."},{"en":"He faithfully visited his grandmother every Sunday for ten years.","vi":"Suốt mười năm, anh ấy tận tụy đến thăm bà vào mỗi Chủ nhật."},{"en":"The movie faithfully follows the story in the original book.","vi":"Bộ phim bám sát câu chuyện trong cuốn sách gốc."}]', '[{"phrase":"Yours faithfully"},{"phrase":"serve faithfully"},{"phrase":"faithfully follow"}]', 'Yours faithfully: câu kết thư trang trọng khi không biết tên người nhận', '/ˈfeɪθfəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fai/faith/faithfully__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-11', 2, 'autumn', 'mùa thu', 'noun', '[{"en":"The leaves on these trees turn red in autumn.","vi":"Lá của những cây này chuyển sang màu đỏ vào mùa thu."},{"en":"We are planning a trip to the mountains next autumn.","vi":"Chúng tôi đang lên kế hoạch đi núi vào mùa thu năm sau."},{"en":"Autumn is my favorite season because the weather is cool.","vi":"Mùa thu là mùa tôi thích nhất vì thời tiết mát mẻ."}]', '[{"phrase":"in autumn"},{"phrase":"next autumn"},{"phrase":"last autumn"},{"phrase":"autumn leaves"}]', 'Anh: autumn · Mỹ: fall', '/ˈɔːtəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aut/autum/autumn__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-11', 3, 'cheek', 'má', 'noun', '[{"en":"She kissed her grandson on the cheek and said goodbye.","vi":"Bà hôn lên má cháu trai rồi chào tạm biệt."},{"en":"Tears were running down his cheeks as he read the letter.","vi":"Nước mắt chảy dài trên má anh ấy khi anh đọc bức thư."},{"en":"The baby has round, pink cheeks and a big smile.","vi":"Em bé có đôi má tròn, hồng hào và nụ cười thật tươi."}]', '[{"phrase":"on the cheek"},{"phrase":"rosy cheeks"},{"phrase":"down his cheeks"}]', NULL, '/tʃiːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/che/cheek/cheek__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-11', 4, 'attachment', 'tệp đính kèm; sự gắn bó', 'noun', '[{"en":"I sent you the report as an attachment this morning.","vi":"Sáng nay tôi đã gửi cho bạn bản báo cáo dưới dạng tệp đính kèm."},{"en":"Please don''t open email attachments from people you don''t know.","vi":"Vui lòng đừng mở tệp đính kèm trong email từ những người bạn không quen biết."},{"en":"Children often form a strong attachment to their first teacher.","vi":"Trẻ em thường rất gắn bó với giáo viên đầu tiên của mình."}]', '[{"phrase":"email attachment"},{"phrase":"send an attachment"},{"phrase":"strong attachment"},{"phrase":"attachment to"}]', NULL, '/əˈtætʃmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attac/attachment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-11', 5, 'holder', 'người giữ, người sở hữu; giá đỡ, đồ đựng', 'noun', '[{"en":"Only ticket holders can enter the stadium after six o''clock.","vi":"Sau sáu giờ, chỉ những người có vé mới được vào sân vận động."},{"en":"She is the current holder of the national swimming record.","vi":"Cô ấy là người đang giữ kỷ lục bơi lội quốc gia."},{"en":"I use a phone holder in the car so I can see the map.","vi":"Tôi dùng giá đỡ điện thoại trên xe để có thể xem bản đồ."}]', '[{"phrase":"ticket holder"},{"phrase":"record holder"},{"phrase":"card holder"},{"phrase":"phone holder"}]', NULL, '/ˈhəʊldər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hol/holde/holder__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-11', 6, 'solar', '(thuộc) mặt trời', 'adjective', '[{"en":"We put solar panels on our roof to save money.","vi":"Chúng tôi lắp tấm pin mặt trời trên mái nhà để tiết kiệm tiền."},{"en":"Solar energy is becoming cheaper and more popular every year.","vi":"Năng lượng mặt trời ngày càng rẻ hơn và phổ biến hơn mỗi năm."},{"en":"Our class made a model of the solar system for the science fair.","vi":"Lớp chúng tôi đã làm mô hình hệ Mặt Trời cho hội chợ khoa học."}]', '[{"phrase":"solar energy"},{"phrase":"solar power"},{"phrase":"solar panel"},{"phrase":"solar system"}]', NULL, '/ˈsəʊlər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sol/solar/solar__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-11', 7, 'grin', 'cười toe toét, cười nhe răng', 'verb', '[{"en":"He grinned when he saw his exam results.","vi":"Cậu ấy cười toe toét khi thấy kết quả thi."},{"en":"The children were grinning from ear to ear at the party.","vi":"Bọn trẻ cười ngoác cả miệng ở bữa tiệc."},{"en":"Why are you grinning at me like that?","vi":"Sao bạn cứ nhe răng cười với tôi như thế?"}]', '[{"phrase":"grin from ear to ear"},{"phrase":"grin at"},{"phrase":"grin broadly"}]', 'grin – grinned – grinned', '/ɡrɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gri/grin_/grin__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-11', 8, 'rose', 'hoa hồng', 'noun', '[{"en":"He gave his wife a dozen red roses on her birthday.","vi":"Anh ấy tặng vợ mười hai bông hồng đỏ vào ngày sinh nhật cô ấy."},{"en":"My grandmother grows beautiful roses in her small garden.","vi":"Bà tôi trồng những bông hồng rất đẹp trong khu vườn nhỏ của bà."},{"en":"A single white rose stood in a glass vase on the table.","vi":"Một bông hồng trắng được cắm trong chiếc bình thủy tinh trên bàn."}]', '[{"phrase":"red roses"},{"phrase":"grow roses"},{"phrase":"a bunch of roses"},{"phrase":"rose garden"}]', 'rose cũng là quá khứ của rise (rise – rose – risen)', '/rəʊz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ros/rose_/rose__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-11', 9, 'noun', 'danh từ', 'noun', '[{"en":"In English, we usually add s to a noun to make it plural.","vi":"Trong tiếng Anh, chúng ta thường thêm s vào danh từ để tạo dạng số nhiều."},{"en":"Can you find all the nouns in this sentence?","vi":"Bạn có thể tìm tất cả các danh từ trong câu này không?"},{"en":"Information is an uncountable noun, so it has no plural form.","vi":"Information là danh từ không đếm được nên không có dạng số nhiều."}]', '[{"phrase":"countable noun"},{"phrase":"uncountable noun"},{"phrase":"plural noun"},{"phrase":"proper noun"}]', NULL, '/naʊn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nou/noun_/noun__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-11', 10, 'fortunate', 'may mắn', 'adjective', '[{"en":"We were fortunate to find a hotel room so late at night.","vi":"Chúng tôi may mắn tìm được phòng khách sạn vào lúc đêm muộn như vậy."},{"en":"I feel very fortunate to have such kind friends.","vi":"Tôi cảm thấy rất may mắn khi có những người bạn tốt bụng như vậy."},{"en":"It was fortunate that nobody was hurt in the accident.","vi":"Thật may là không ai bị thương trong vụ tai nạn."}]', '[{"phrase":"fortunate to"},{"phrase":"fortunate enough"},{"phrase":"feel fortunate"},{"phrase":"less fortunate"}]', NULL, '/ˈfɔːrtʃənət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/fortu/fortunate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-11', 11, 'alright', 'ổn, không sao; được rồi', 'adjective', '[{"en":"You look pale. Are you feeling alright?","vi":"Trông bạn xanh xao quá. Bạn thấy ổn chứ?"},{"en":"Don''t worry, everything will be alright in the end.","vi":"Đừng lo, cuối cùng mọi chuyện sẽ ổn thôi."},{"en":"Alright, let''s take a short break and meet back here at three.","vi":"Được rồi, chúng ta nghỉ một chút rồi gặp lại ở đây lúc ba giờ."}]', '[{"phrase":"feel alright"},{"phrase":"be alright"},{"phrase":"it''s alright"}]', '= all right (all right trang trọng hơn)', '/ɔːlˈraɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/all/all_r/all_right_1_us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-11', 12, 'lazy', 'lười biếng; thong thả, nhàn nhã', 'adjective', '[{"en":"My brother is too lazy to clean his own room.","vi":"Em trai tôi lười đến mức không chịu tự dọn phòng của mình."},{"en":"Don''t be lazy; finish your homework before dinner.","vi":"Đừng lười biếng, hãy làm xong bài tập trước bữa tối."},{"en":"We spent a lazy Sunday afternoon reading in the garden.","vi":"Chúng tôi đã có một buổi chiều Chủ nhật thong thả đọc sách trong vườn."}]', '[{"phrase":"too lazy to"},{"phrase":"lazy afternoon"},{"phrase":"lazy day"},{"phrase":"feel lazy"}]', NULL, '/ˈleɪzi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/laz/lazy_/lazy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-11', 13, 'hello', 'xin chào; a lô', 'exclamation', '[{"en":"Hello, I''m your new neighbor from the apartment upstairs.","vi":"Xin chào, tôi là hàng xóm mới ở căn hộ tầng trên."},{"en":"When I answered the phone and said hello, nobody replied.","vi":"Khi tôi nhấc máy và nói a lô, không ai trả lời cả."},{"en":"Please say hello to your parents for me.","vi":"Cho tôi gửi lời chào đến bố mẹ bạn nhé."}]', '[{"phrase":"say hello"},{"phrase":"say hello to"},{"phrase":"hello again"}]', NULL, '/həˈləʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hel/hello/hello__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-11', 14, 'hunger', 'cơn đói, sự đói; sự khao khát', 'noun', '[{"en":"After the long hike, we were all weak with hunger.","vi":"Sau chuyến đi bộ dài, tất cả chúng tôi đều lả đi vì đói."},{"en":"Drinking water can help you control your hunger between meals.","vi":"Uống nước có thể giúp bạn kiềm chế cơn đói giữa các bữa ăn."},{"en":"She has a real hunger for knowledge and reads every day.","vi":"Cô ấy thực sự khao khát tri thức và đọc sách mỗi ngày."}]', '[{"phrase":"weak with hunger"},{"phrase":"hunger for knowledge"},{"phrase":"hunger pangs"}]', NULL, '/ˈhʌŋɡər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hun/hunge/hunger__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-11', 15, 'insure', 'bảo hiểm, mua bảo hiểm', 'verb', '[{"en":"You should insure your car before driving it on the road.","vi":"Bạn nên mua bảo hiểm cho xe trước khi lái nó ra đường."},{"en":"Our house is insured against fire and flood damage.","vi":"Ngôi nhà của chúng tôi được bảo hiểm chống hỏa hoạn và thiệt hại do lũ lụt."},{"en":"The company refused to insure him because of his health problems.","vi":"Công ty đã từ chối bảo hiểm cho anh ấy vì các vấn đề sức khỏe."}]', '[{"phrase":"insure against"},{"phrase":"fully insured"},{"phrase":"insure your car"}]', 'insure (bảo hiểm) ≠ ensure (đảm bảo)', '/ɪnˈʃʊr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insur/insure__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-11', 16, 'ashamed', 'xấu hổ, hổ thẹn', 'adjective', '[{"en":"I was ashamed of the way I spoke to my mother.","vi":"Tôi thấy xấu hổ vì cách mình đã nói chuyện với mẹ."},{"en":"You have nothing to be ashamed of.","vi":"Bạn không có gì phải xấu hổ cả."},{"en":"He felt too ashamed to tell anyone about his mistake.","vi":"Anh ấy xấu hổ đến mức không dám kể với ai về sai lầm của mình."}]', '[{"phrase":"ashamed of"},{"phrase":"feel ashamed"},{"phrase":"deeply ashamed"},{"phrase":"ashamed to admit"}]', 'đi với giới từ of: be ashamed of something', '/əˈʃeɪmd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ash/asham/ashamed__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-11', 17, 'found', 'thành lập, sáng lập', 'verb', '[{"en":"My grandfather founded this small bakery fifty years ago.","vi":"Ông tôi đã thành lập tiệm bánh nhỏ này cách đây năm mươi năm."},{"en":"The school was founded in 1920 by a group of teachers.","vi":"Ngôi trường do một nhóm giáo viên thành lập vào năm 1920."},{"en":"They plan to found a charity to help children in poor areas.","vi":"Họ dự định thành lập một tổ chức từ thiện để giúp đỡ trẻ em ở vùng nghèo."}]', '[{"phrase":"found a company"},{"phrase":"found a charity"},{"phrase":"founded in"},{"phrase":"newly founded"}]', 'found – founded – founded; khác với found (quá khứ của find)', '/faʊnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fou/found/found__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-11', 18, 'blog', 'blog, nhật ký trên mạng', 'noun', '[{"en":"She writes a travel blog about her trips around Asia.","vi":"Cô ấy viết blog du lịch về những chuyến đi vòng quanh châu Á."},{"en":"I read an interesting blog post about healthy cooking today.","vi":"Hôm nay tôi đọc một bài blog thú vị về nấu ăn lành mạnh."},{"en":"He started a blog to share tips for new parents.","vi":"Anh ấy lập một blog để chia sẻ mẹo cho những người mới làm cha mẹ."}]', '[{"phrase":"blog post"},{"phrase":"start a blog"},{"phrase":"write a blog"},{"phrase":"travel blog"}]', NULL, '/blɑːɡ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/blo/blog_/blog__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-11', 19, 'thirst', 'cơn khát, sự khát; sự khao khát', 'noun', '[{"en":"We were dying of thirst after playing football all afternoon.","vi":"Chúng tôi khát khô cả cổ sau khi đá bóng suốt buổi chiều."},{"en":"On hot days, people often mistake thirst for hunger.","vi":"Vào những ngày nóng, người ta thường nhầm cơn khát thành cơn đói."},{"en":"Many young people have a strong thirst for adventure.","vi":"Nhiều người trẻ có niềm khao khát phiêu lưu mãnh liệt."}]', '[{"phrase":"quench your thirst"},{"phrase":"dying of thirst"},{"phrase":"thirst for adventure"}]', NULL, '/θɜːrst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thi/thirs/thirst__us_1.mp3', NULL, NULL);
